<?php

declare(strict_types=1);

namespace PortLibs\Pandoc;

final class OdfReader
{
    public const MIMETYPE = 'application/vnd.oasis.opendocument.text';
    private const OFFICE_NS = 'urn:oasis:names:tc:opendocument:xmlns:office:1.0';
    private const TEXT_NS = 'urn:oasis:names:tc:opendocument:xmlns:text:1.0';
    private const STYLE_NS = 'urn:oasis:names:tc:opendocument:xmlns:style:1.0';
    private const TABLE_NS = 'urn:oasis:names:tc:opendocument:xmlns:table:1.0';
    private const NUMBER_NS = 'urn:oasis:names:tc:opendocument:xmlns:datastyle:1.0';
    private const DRAW_NS = 'urn:oasis:names:tc:opendocument:xmlns:drawing:1.0';
    private const FORM_NS = 'urn:oasis:names:tc:opendocument:xmlns:form:1.0';
    private const SVG_NS = 'urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0';
    private const XLINK_NS = 'http://www.w3.org/1999/xlink';
    private const SCRIPT_NS = 'urn:oasis:names:tc:opendocument:xmlns:script:1.0';
    private const MANIFEST_NS = 'urn:oasis:names:tc:opendocument:xmlns:manifest:1.0';
    private const CONFIG_NS = 'urn:oasis:names:tc:opendocument:xmlns:config:1.0';
    private const DC_NS = 'http://purl.org/dc/elements/1.1/';
    private const META_NS = 'urn:oasis:names:tc:opendocument:xmlns:meta:1.0';
    private const FO_NS = 'urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0';
    private const MATH_NS = 'http://www.w3.org/1998/Math/MathML';
    private const CHART_NS = 'urn:oasis:names:tc:opendocument:xmlns:chart:1.0';
    private const XML_NS = 'http://www.w3.org/XML/1998/namespace';
    private const RDF_NS = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#';
    private const XHTML_NS = 'http://www.w3.org/1999/xhtml';
    private const DSIG_NS = 'http://www.w3.org/2000/09/xmldsig#';
    private const XMLNS_NS = 'http://www.w3.org/2000/xmlns/';
    private const MANIFEST_FILE_ENTRY_STRUCTURAL_ATTRIBUTES = [
        'full-path' => true,
        'media-type' => true,
        'preferred-view-mode' => true,
        'size' => true,
        'version' => true,
    ];
    private const MANIFEST_FILE_ENTRY_STRUCTURAL_CHILD_ELEMENTS = [
        'encryption-data' => true,
    ];
    private const MANIFEST_ROOT_STRUCTURAL_ATTRIBUTES = [
        'version' => true,
    ];
    private const OFFICE_DOCUMENT_ROOT_STRUCTURAL_ATTRIBUTES = [
        'version' => true,
    ];
    private const PREFERRED_VIEW_MODE_VALUES = [
        'edit' => true,
        'presentation-slide-show' => true,
        'read-only' => true,
    ];

    /** @var array<string, array<string, mixed>> */
    private array $trackedChanges = [];

    /** @var array<string, array<string, mixed>> */
    private array $manifestByPart = [];

    private string $manifestVersion = '';

    /** @var array<string, mixed> */
    private array $manifestRootAttributeProvenance = [];

    /** @var array<string, mixed> */
    private array $manifestRootExtensionElementProvenance = [];

    /** @var array<string, array<string, mixed>> */
    private array $formControlsById = [];

    /** @var array<string, mixed> */
    private array $contentDeclarations = [];

    /** @var array<int, int> */
    private array $listContinuationStartCounters = [];

    /** @var array<string, array<int, int>> */
    private array $listContinuationStartCountersById = [];

    /** @var list<string> */
    private array $currentListStyleNames = [];

    private int $currentListLevel = 0;

    /** @var array<string, int> */
    private array $headingAnchorUses = [];

    /** @var array<string, array<string, mixed>> */
    private array $variableFieldValuesByName = [];

    /** @var array<string, mixed> */
    private array $packageMetadata = [];

    /** @var array<string, mixed> */
    private array $packageSettings = [];

    /** @var array<string, mixed> */
    private array $packageRdfMetadata = [];

    /**
     * @return array{
     *     document:AstNode,
     *     metadata:array<string, mixed>,
     *     manifest:list<array<string, mixed>>,
     *     styles:array<string, mixed>,
     *     fontFaces:array<string, mixed>,
     *     listStyles:array<string, mixed>,
     *     dataStyles:array<string, mixed>,
     *     tableTemplates:array<string, mixed>,
     *     pageLayouts:array<string, mixed>,
     *     masterPages:array<string, mixed>,
     *     settings:array<string, mixed>,
     *     contentDeclarations:array<string, mixed>,
     *     media:list<array<string, mixed>>,
     *     packageThumbnails:array<string, mixed>,
     *     packageSignatures:array<string, mixed>,
     *     packageFonts:array<string, mixed>,
     *     packageConfigurations:array<string, mixed>,
     *     packageObjectReplacements:array<string, mixed>,
     *     packageScripts:array<string, mixed>,
     *     packageLayoutCaches:array<string, mixed>,
     *     documentPartVersions:array<string, mixed>,
     *     rdfMetadata:array<string, mixed>,
     *     signatureMetadata:array<string, mixed>,
     *     scriptMetadata:array<string, mixed>,
     *     trackedChanges:list<array<string, mixed>>,
     *     importReport:array<string, mixed>
     * }
     */
    public function readPackage(ZipPackage $package): array
    {
        $mimetypeEntry = $this->assertOdtMimetype($package);

        $manifest = $this->readManifest($package);
        $this->manifestByPart = $this->manifestByPart($manifest);
        $manifestRootAttributes = $this->manifestRootAttributeProvenance;
        $manifestRootExtensions = $this->manifestRootExtensionElementProvenance;
        $rdfMetadata = $this->readRdfMetadata($package, $manifest);
        $signatureMetadata = $this->readSignatureMetadata($package, $manifest);
        $this->packageRdfMetadata = $rdfMetadata;
        $styleCatalog = $this->readStyles($package);
        $metadata = $this->readMeta($package);
        $settings = $this->readSettings($package);
        $content = $this->readContent($package, $styleCatalog, $metadata, $settings);
        $contentStats = $this->contentNodeStats($content['blocks']);
        $styleCatalog = $content['styleCatalog'];
        $styleDiagnostics = array_merge(
            $this->styleDiagnostics($styleCatalog),
            $content['styleReferenceDiagnostics']
        );
        $media = $this->mediaReport($package, $manifest);
        $scriptMetadata = $this->readScriptMetadata($package, $manifest, $content['blocks']);
        $encryptedItems = $this->encryptedManifestItems($manifest);
        $manifestEncryptionSummary = self::manifestEncryptionSummary($manifest);
        $declaredSizeMismatches = $this->manifestDeclaredSizeMismatches($manifest);
        $directoryItems = $this->manifestDirectoryItems($manifest);
        $manifestMediaTypeSummary = $this->manifestMediaTypeSummary($manifest);
        $undeclaredEntries = $this->manifestUndeclaredPackageEntries($package, $manifest);
        $packageThumbnails = $this->packageThumbnailMetadata($package, $manifest, $undeclaredEntries);
        $packageSignatures = $this->packageSignatureMetadata($package, $manifest, $undeclaredEntries);
        $packageFonts = $this->packageFontMetadata($package, $manifest, $undeclaredEntries);
        $packageConfigurations = $this->packageConfigurationMetadata($package, $manifest, $undeclaredEntries);
        $packageObjectReplacements = $this->packageObjectReplacementMetadata($package, $manifest, $undeclaredEntries);
        $packageScripts = $this->packageScriptMetadata($package, $manifest, $undeclaredEntries);
        $packageLayoutCaches = $this->packageLayoutCacheMetadata($package, $manifest, $undeclaredEntries);
        $packageProvenance = $this->packageProvenance($package, $manifest, $mimetypeEntry, $undeclaredEntries, $styleCatalog, $styleDiagnostics);
        $documentPartVersions = $this->documentPartVersionMetadata($package, $manifest);
        if ($packageThumbnails['count'] > 0) {
            $metadata['odfPackageThumbnails'] = $packageThumbnails;
        }
        if ($packageSignatures['count'] > 0) {
            $metadata['odfPackageSignatures'] = $packageSignatures;
        }
        if ($packageFonts['count'] > 0) {
            $metadata['odfPackageFonts'] = $packageFonts;
        }
        if ($packageConfigurations['count'] > 0) {
            $metadata['odfPackageConfigurations'] = $packageConfigurations;
        }
        if ($packageObjectReplacements['count'] > 0) {
            $metadata['odfPackageObjectReplacements'] = $packageObjectReplacements;
        }
        if ($packageScripts['count'] > 0) {
            $metadata['odfPackageScripts'] = $packageScripts;
        }
        if ($packageLayoutCaches['count'] > 0) {
            $metadata['odfPackageLayoutCaches'] = $packageLayoutCaches;
        }

        $document = new AstNode('document', [
            'source' => 'odt',
            'metadata' => $metadata,
            'title' => (string) ($metadata['title'] ?? ''),
            'manifest' => [
                'mimetype' => self::MIMETYPE,
                'version' => $this->manifestVersion === '' ? null : $this->manifestVersion,
                'rootAttributeCount' => $manifestRootAttributes['attributeCount'] ?? 0,
                'rootAttributeNames' => $manifestRootAttributes['attributeNames'] ?? [],
                'rootAttributes' => $manifestRootAttributes['attributes'] ?? [],
                'rootCustomAttributeCount' => $manifestRootAttributes['customAttributeCount'] ?? 0,
                'rootCustomAttributeNames' => $manifestRootAttributes['customAttributeNames'] ?? [],
                'rootCustomAttributes' => $manifestRootAttributes['customAttributes'] ?? [],
                'rootCustomAttributeMap' => $manifestRootAttributes['customAttributeMap'] ?? [],
                'rootNamespaceDeclarationCount' => $manifestRootAttributes['namespaceDeclarationCount'] ?? 0,
                'rootNamespaceDeclarationNames' => $manifestRootAttributes['namespaceDeclarationNames'] ?? [],
                'rootNamespaceDeclarations' => $manifestRootAttributes['namespaceDeclarations'] ?? [],
                'rootNamespaceDeclarationMap' => $manifestRootAttributes['namespaceDeclarationMap'] ?? [],
                'rootExtensionElementCount' => $manifestRootExtensions['extensionElementCount'] ?? 0,
                'rootExtensionElementNames' => $manifestRootExtensions['extensionElementNames'] ?? [],
                'rootExtensionElements' => $manifestRootExtensions['extensionElements'] ?? [],
                'mimetypeEntry' => $mimetypeEntry,
                'items' => $manifest,
                'mediaTypeSummary' => $manifestMediaTypeSummary,
                'packageProvenance' => $packageProvenance,
                'documentPartVersions' => $documentPartVersions,
                'encryption' => $manifestEncryptionSummary,
            ],
            'styles' => [
                'count' => count($styleCatalog['styles']),
                'items' => array_values($styleCatalog['styles']),
                'diagnosticCount' => count($styleDiagnostics),
                'diagnosticCodeCounts' => $this->diagnosticCodeCounts($styleDiagnostics),
                'diagnostics' => $styleDiagnostics,
            ],
            'fontFaces' => [
                'count' => count($styleCatalog['fontFaces']),
                'items' => array_values($styleCatalog['fontFaces']),
            ],
            'listStyles' => [
                'count' => count($styleCatalog['listStyles']),
                'items' => array_values($styleCatalog['listStyles']),
            ],
            'dataStyles' => [
                'count' => count($styleCatalog['dataStyles']),
                'items' => array_values($styleCatalog['dataStyles']),
            ],
            'tableTemplates' => [
                'count' => count($styleCatalog['tableTemplates']),
                'items' => array_values($styleCatalog['tableTemplates']),
            ],
            'pageLayouts' => [
                'count' => count($styleCatalog['pageLayouts']),
                'items' => array_values($styleCatalog['pageLayouts']),
            ],
            'masterPages' => [
                'count' => count($styleCatalog['masterPages']),
                'items' => array_values($styleCatalog['masterPages']),
            ],
            'settings' => $settings,
            'contentDeclarations' => $content['contentDeclarations'],
            'rdfMetadata' => $rdfMetadata,
            'signatureMetadata' => $signatureMetadata,
            'scriptMetadata' => $scriptMetadata,
            'packageThumbnails' => $packageThumbnails,
            'packageSignatures' => $packageSignatures,
            'packageFonts' => $packageFonts,
            'packageConfigurations' => $packageConfigurations,
            'packageObjectReplacements' => $packageObjectReplacements,
            'packageScripts' => $packageScripts,
            'packageLayoutCaches' => $packageLayoutCaches,
            'trackedChanges' => [
                'count' => count($content['trackedChanges']),
                'items' => $content['trackedChanges'],
            ],
        ], $content['blocks']);

        return [
            'document' => $document,
            'metadata' => $metadata,
            'manifest' => $manifest,
            'styles' => $styleCatalog['styles'],
            'fontFaces' => $styleCatalog['fontFaces'],
            'listStyles' => $styleCatalog['listStyles'],
            'dataStyles' => $styleCatalog['dataStyles'],
            'tableTemplates' => $styleCatalog['tableTemplates'],
            'pageLayouts' => $styleCatalog['pageLayouts'],
            'masterPages' => $styleCatalog['masterPages'],
            'settings' => $settings,
            'contentDeclarations' => $content['contentDeclarations'],
            'media' => $media,
            'packageThumbnails' => $packageThumbnails,
            'packageSignatures' => $packageSignatures,
            'packageFonts' => $packageFonts,
            'packageConfigurations' => $packageConfigurations,
            'packageObjectReplacements' => $packageObjectReplacements,
            'packageScripts' => $packageScripts,
            'packageLayoutCaches' => $packageLayoutCaches,
            'documentPartVersions' => $documentPartVersions,
            'rdfMetadata' => $rdfMetadata,
            'signatureMetadata' => $signatureMetadata,
            'scriptMetadata' => $scriptMetadata,
            'trackedChanges' => $content['trackedChanges'],
            'importReport' => [
                'mimetype' => self::MIMETYPE,
                'manifest' => [
                    'count' => count($manifest),
                    'version' => $this->manifestVersion === '' ? null : $this->manifestVersion,
                    'rootAttributeCount' => $manifestRootAttributes['attributeCount'] ?? 0,
                    'rootAttributeNames' => $manifestRootAttributes['attributeNames'] ?? [],
                    'rootAttributes' => $manifestRootAttributes['attributes'] ?? [],
                    'rootCustomAttributeCount' => $manifestRootAttributes['customAttributeCount'] ?? 0,
                    'rootCustomAttributeNames' => $manifestRootAttributes['customAttributeNames'] ?? [],
                    'rootCustomAttributes' => $manifestRootAttributes['customAttributes'] ?? [],
                    'rootCustomAttributeMap' => $manifestRootAttributes['customAttributeMap'] ?? [],
                    'rootNamespaceDeclarationCount' => $manifestRootAttributes['namespaceDeclarationCount'] ?? 0,
                    'rootNamespaceDeclarationNames' => $manifestRootAttributes['namespaceDeclarationNames'] ?? [],
                    'rootNamespaceDeclarations' => $manifestRootAttributes['namespaceDeclarations'] ?? [],
                    'rootNamespaceDeclarationMap' => $manifestRootAttributes['namespaceDeclarationMap'] ?? [],
                    'rootExtensionElementCount' => $manifestRootExtensions['extensionElementCount'] ?? 0,
                    'rootExtensionElementNames' => $manifestRootExtensions['extensionElementNames'] ?? [],
                    'rootExtensionElements' => $manifestRootExtensions['extensionElements'] ?? [],
                    'mimetypeEntry' => $mimetypeEntry,
                    'items' => $manifest,
                    'mediaTypeSummary' => $manifestMediaTypeSummary,
                    'packageProvenance' => $packageProvenance,
                    'documentPartVersions' => $documentPartVersions,
                    'directoryCount' => count($directoryItems),
                    'directoryItems' => $directoryItems,
                    'missingItems' => array_values(array_filter(
                        $manifest,
                        static fn (array $item): bool => ($item['exists'] ?? false) !== true,
                    )),
                    'undeclaredEntryCount' => count($undeclaredEntries),
                    'undeclaredEntries' => $undeclaredEntries,
                    'encryptedCount' => count($encryptedItems),
                    'encryptedItems' => $encryptedItems,
                    'encryption' => $manifestEncryptionSummary,
                    'declaredSizeMismatchCount' => count($declaredSizeMismatches),
                    'declaredSizeMismatches' => $declaredSizeMismatches,
                ],
                'metadata' => $metadata,
                'styles' => [
                    'count' => count($styleCatalog['styles']),
                    'items' => array_values($styleCatalog['styles']),
                    'pageLayoutCount' => count($styleCatalog['pageLayouts']),
                    'masterPageCount' => count($styleCatalog['masterPages']),
                    'tableTemplateCount' => count($styleCatalog['tableTemplates']),
                    'dataStyleCount' => count($styleCatalog['dataStyles']),
                    'dataStyles' => array_values($styleCatalog['dataStyles']),
                    'fontFaceCount' => count($styleCatalog['fontFaces']),
                    'fontFaces' => array_values($styleCatalog['fontFaces']),
                    'styleMapCount' => $this->styleMapCount($styleCatalog['styles']),
                    'diagnosticCount' => count($styleDiagnostics),
                    'diagnosticCodeCounts' => $this->diagnosticCodeCounts($styleDiagnostics),
                    'diagnostics' => $styleDiagnostics,
                ],
                'listStyles' => [
                    'count' => count($styleCatalog['listStyles']),
                    'items' => array_values($styleCatalog['listStyles']),
                ],
                'tableTemplates' => [
                    'count' => count($styleCatalog['tableTemplates']),
                    'items' => array_values($styleCatalog['tableTemplates']),
                ],
                'pageLayouts' => [
                    'count' => count($styleCatalog['pageLayouts']),
                    'items' => array_values($styleCatalog['pageLayouts']),
                ],
                'masterPages' => [
                    'count' => count($styleCatalog['masterPages']),
                    'items' => array_values($styleCatalog['masterPages']),
                ],
                'settings' => $settings,
                'contentDeclarations' => $content['contentDeclarations'],
                'media' => [
                    'count' => count($media),
                    'items' => $media,
                ],
                'packageThumbnails' => $packageThumbnails,
                'packageSignatures' => $packageSignatures,
                'packageFonts' => $packageFonts,
                'packageConfigurations' => $packageConfigurations,
                'packageObjectReplacements' => $packageObjectReplacements,
                'packageScripts' => $packageScripts,
                'packageLayoutCaches' => $packageLayoutCaches,
                'rdfMetadata' => $rdfMetadata,
                'signatureMetadata' => $signatureMetadata,
                'scriptMetadata' => $scriptMetadata,
                'trackedChanges' => [
                    'count' => count($content['trackedChanges']),
                    'items' => $content['trackedChanges'],
                ],
                'encryption' => [
                    'count' => count($encryptedItems),
                    'encryptedParts' => array_values(array_filter(
                        array_map(static fn (array $item): ?string => is_string($item['part'] ?? null) ? $item['part'] : null, $encryptedItems),
                        static fn (?string $part): bool => $part !== null && $part !== ''
                    )),
                    'summary' => $manifestEncryptionSummary,
                    'items' => $encryptedItems,
                ],
                'content' => [
                    'blockCount' => count($content['blocks']),
                    'automaticStyleCount' => $content['automaticStyleCount'],
                    'blockquoteCount' => $contentStats['blockquoteCount'],
                    'noteCount' => $contentStats['noteCount'],
                    'bookmarkCount' => $contentStats['bookmarkCount'],
                    'bookmarkReferenceCount' => $contentStats['bookmarkReferenceCount'],
                    'referenceMarkCount' => $contentStats['referenceMarkCount'],
                    'referenceReferenceCount' => $contentStats['referenceReferenceCount'],
                    'indexMarkCount' => $contentStats['indexMarkCount'],
                    'sequenceCount' => $contentStats['sequenceCount'],
                    'fieldCount' => $contentStats['fieldCount'],
                    'metaSpanCount' => $contentStats['metaSpanCount'],
                    'placeholderCount' => $contentStats['placeholderCount'],
                    'rubyCount' => $contentStats['rubyCount'],
                    'softPageBreakCount' => $contentStats['softPageBreakCount'],
                    'citationCount' => $contentStats['citationCount'],
                    'eventListenerCount' => $contentStats['eventListenerCount'],
                    'annotationRangeCount' => $contentStats['annotationRangeCount'],
                    'trackedChangeCount' => $contentStats['trackedChangeCount'],
                    'mathCount' => $contentStats['mathCount'],
                    'embeddedObjectCount' => $contentStats['embeddedObjectCount'],
                    'missingEmbeddedObjectCount' => $contentStats['missingEmbeddedObjectCount'],
                    'chartObjectCount' => $contentStats['chartObjectCount'],
                    'chartMetadataCount' => $contentStats['chartMetadataCount'],
                    'chartTitleCount' => $contentStats['chartTitleCount'],
                    'chartAxisCount' => $contentStats['chartAxisCount'],
                    'chartLegendCount' => $contentStats['chartLegendCount'],
                    'formControlCount' => $contentStats['formControlCount'],
                    'missingFormControlCount' => $contentStats['missingFormControlCount'],
                    'formControlOptionCount' => $contentStats['formControlOptionCount'],
                    'selectedFormControlOptionCount' => $contentStats['selectedFormControlOptionCount'],
                    'sectionCount' => $contentStats['sectionCount'],
                    'linkedSectionCount' => $contentStats['linkedSectionCount'],
                    'protectedSectionCount' => $contentStats['protectedSectionCount'],
                    'conditionalSectionCount' => $contentStats['conditionalSectionCount'],
                    'hiddenSectionCount' => $contentStats['hiddenSectionCount'],
                    'tableOfContentsCount' => $contentStats['tableOfContentsCount'],
                    'generatedIndexCount' => $contentStats['generatedIndexCount'],
                    'tableCaptionCount' => $contentStats['tableCaptionCount'],
                    'preformattedCodeBlockCount' => $contentStats['preformattedCodeBlockCount'],
                    'continuedListCount' => $contentStats['continuedListCount'],
                    'listHeaderCount' => $contentStats['listHeaderCount'],
                    'imageListStyleCount' => $contentStats['imageListStyleCount'],
                    'listTextPropertyCount' => $contentStats['listTextPropertyCount'],
                    'tableTemplateReferenceCount' => $contentStats['tableTemplateReferenceCount'],
                    'tablePrintRangeCount' => $contentStats['tablePrintRangeCount'],
                    'tableScenarioCount' => $contentStats['tableScenarioCount'],
                    'activeTableScenarioCount' => $contentStats['activeTableScenarioCount'],
                    'tableColumnDefinitionCount' => $contentStats['tableColumnDefinitionCount'],
                    'hiddenTableColumnCount' => $contentStats['hiddenTableColumnCount'],
                    'tableRowDefinitionCount' => $contentStats['tableRowDefinitionCount'],
                    'hiddenTableRowCount' => $contentStats['hiddenTableRowCount'],
                    'repeatedTableRowCount' => $contentStats['repeatedTableRowCount'],
                    'truncatedTableRowRepeatCount' => $contentStats['truncatedTableRowRepeatCount'],
                    'tableCoveredCellCount' => $contentStats['tableCoveredCellCount'],
                    'tableCoveredCellMetadataCount' => $contentStats['tableCoveredCellMetadataCount'],
                    'tableCellAnnotationCount' => $contentStats['tableCellAnnotationCount'],
                    'tableCellDetectiveCount' => $contentStats['tableCellDetectiveCount'],
                    'tableCellDetectiveHighlightCount' => $contentStats['tableCellDetectiveHighlightCount'],
                    'tableCellDetectiveOperationCount' => $contentStats['tableCellDetectiveOperationCount'],
                    'tableStyledCellCount' => $contentStats['tableStyledCellCount'],
                    'tableDataStyledCellCount' => $contentStats['tableDataStyledCellCount'],
                    'tableDataStyleDefinitionCellCount' => $contentStats['tableDataStyleDefinitionCellCount'],
                    'tableProtectedCellCount' => $contentStats['tableProtectedCellCount'],
                    'tablePrintHiddenCellCount' => $contentStats['tablePrintHiddenCellCount'],
                    'frameCaptionCount' => $contentStats['frameCaptionCount'],
                    'noteConfigurationCount' => (int) ($content['contentDeclarations']['noteConfigurationCount'] ?? 0),
                    'noteConfigurationSeparatorCount' => (int) ($content['contentDeclarations']['noteConfigurationSeparatorCount'] ?? 0),
                    'lineNumberingConfigurationCount' => (int) ($content['contentDeclarations']['lineNumberingConfigurationCount'] ?? 0),
                    'lineNumberingSeparatorCount' => (int) ($content['contentDeclarations']['lineNumberingSeparatorCount'] ?? 0),
                    'contentValidationCount' => (int) ($content['contentDeclarations']['contentValidationCount'] ?? 0),
                    'contentValidationConditionCount' => (int) ($content['contentDeclarations']['contentValidationConditionCount'] ?? 0),
                    'contentValidationMessageCount' => (int) ($content['contentDeclarations']['contentValidationMessageCount'] ?? 0),
                    'labelRangeCount' => (int) ($content['contentDeclarations']['labelRangeCount'] ?? 0),
                    'calculationSettingCount' => (int) ($content['contentDeclarations']['calculationSettingCount'] ?? 0),
                    'consolidationCount' => (int) ($content['contentDeclarations']['consolidationCount'] ?? 0),
                    'consolidationSourceRangeCount' => (int) ($content['contentDeclarations']['consolidationSourceRangeCount'] ?? 0),
                    'namedExpressionCount' => (int) ($content['contentDeclarations']['namedExpressionCount'] ?? 0),
                    'namedRangeCount' => (int) ($content['contentDeclarations']['namedRangeCount'] ?? 0),
                    'namedFormulaExpressionCount' => (int) ($content['contentDeclarations']['namedFormulaExpressionCount'] ?? 0),
                    'namedExpressionDuplicateNameCount' => (int) ($content['contentDeclarations']['namedExpressionDuplicateNameCount'] ?? 0),
                    'namedExpressionDuplicateEntryCount' => (int) ($content['contentDeclarations']['namedExpressionDuplicateEntryCount'] ?? 0),
                    'databaseRangeCount' => (int) ($content['contentDeclarations']['databaseRangeCount'] ?? 0),
                    'databaseSubtotalRuleCount' => (int) ($content['contentDeclarations']['databaseSubtotalRuleCount'] ?? 0),
                    'databaseSubtotalFieldCount' => (int) ($content['contentDeclarations']['databaseSubtotalFieldCount'] ?? 0),
                    'dataPilotTableCount' => (int) ($content['contentDeclarations']['dataPilotTableCount'] ?? 0),
                    'dataPilotFieldCount' => (int) ($content['contentDeclarations']['dataPilotFieldCount'] ?? 0),
                    'dataPilotSubtotalCount' => (int) ($content['contentDeclarations']['dataPilotSubtotalCount'] ?? 0),
                    'dataPilotMemberCount' => (int) ($content['contentDeclarations']['dataPilotMemberCount'] ?? 0),
                    'dataPilotDisplayInfoCount' => (int) ($content['contentDeclarations']['dataPilotDisplayInfoCount'] ?? 0),
                    'dataPilotSortInfoCount' => (int) ($content['contentDeclarations']['dataPilotSortInfoCount'] ?? 0),
                    'dataPilotLayoutInfoCount' => (int) ($content['contentDeclarations']['dataPilotLayoutInfoCount'] ?? 0),
                    'dataPilotFieldReferenceCount' => (int) ($content['contentDeclarations']['dataPilotFieldReferenceCount'] ?? 0),
                    'dataPilotGroupCount' => (int) ($content['contentDeclarations']['dataPilotGroupCount'] ?? 0),
                    'dataPilotGroupMemberCount' => (int) ($content['contentDeclarations']['dataPilotGroupMemberCount'] ?? 0),
                    'tableTrackedChangeCount' => (int) ($content['contentDeclarations']['tableTrackedChangeCount'] ?? 0),
                    'ddeConnectionDeclarationCount' => (int) ($content['contentDeclarations']['ddeConnectionDeclarationCount'] ?? 0),
                    'drawLayerCount' => (int) ($content['contentDeclarations']['drawLayerCount'] ?? 0),
                    'hiddenDrawLayerCount' => (int) ($content['contentDeclarations']['hiddenDrawLayerCount'] ?? 0),
                    'protectedDrawLayerCount' => (int) ($content['contentDeclarations']['protectedDrawLayerCount'] ?? 0),
                    'frameLayerReferenceCount' => $contentStats['frameLayerReferenceCount'],
                ],
            ],
        ];
    }

    public function readDocument(ZipPackage $package): AstNode
    {
        return $this->readPackage($package)['document'];
    }

    /**
     * @return array<string, mixed>
     */
    private function assertOdtMimetype(ZipPackage $package): array
    {
        return $package->assertStoredFirstEntry('mimetype', self::MIMETYPE, 'ODT mimetype entry');
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function readManifest(ZipPackage $package): array
    {
        if (!$package->has('META-INF/manifest.xml')) {
            throw new \RuntimeException('ODT package is missing META-INF/manifest.xml');
        }

        $dom = self::loadXml($package->read('META-INF/manifest.xml'), 'ODT manifest XML');
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || $root->localName !== 'manifest' || $root->namespaceURI !== self::MANIFEST_NS) {
            throw new \InvalidArgumentException('ODT manifest XML must use manifest:manifest as its root element');
        }

        $this->manifestVersion = self::attr($root, self::MANIFEST_NS, 'version');
        $this->manifestRootAttributeProvenance = $this->manifestRootAttributeProvenance($root);
        $this->manifestRootExtensionElementProvenance = $this->manifestRootExtensionElementProvenance($root);
        $rawItems = [];
        $seenFullPaths = [];
        $seenParts = [];
        $rootMediaType = null;
        $hasContentXml = false;
        $manifestIndex = 0;
        foreach (self::childElements($root, 'file-entry', self::MANIFEST_NS) as $entryElement) {
            $fullPath = self::attr($entryElement, self::MANIFEST_NS, 'full-path');
            if ($fullPath === '') {
                throw new \RuntimeException('ODT manifest file-entry is missing manifest:full-path');
            }
            if (isset($seenFullPaths[$fullPath])) {
                throw new \RuntimeException('Duplicate ODT manifest full-path: ' . $fullPath);
            }
            $seenFullPaths[$fullPath] = true;

            $mediaType = self::attr($entryElement, self::MANIFEST_NS, 'media-type');
            $mediaTypeReport = self::mediaTypeReport($mediaType);
            $version = self::attr($entryElement, self::MANIFEST_NS, 'version');
            $preferredViewMode = self::attr($entryElement, self::MANIFEST_NS, 'preferred-view-mode');
            $declaredSize = self::manifestDeclaredSize(self::attr($entryElement, self::MANIFEST_NS, 'size'));
            $attributeProvenance = $this->manifestFileEntryAttributeProvenance($entryElement);
            $childElementProvenance = $this->manifestFileEntryChildElementProvenance($entryElement);
            $encryptionElements = self::childElements($entryElement, 'encryption-data', self::MANIFEST_NS);
            $encrypted = $encryptionElements !== [];
            $packageReference = $fullPath === '/' ? self::rootManifestPackageReference() : $this->manifestPackageReference($fullPath, false);
            $part = $packageReference['part'];
            if (is_string($part) && $part !== '') {
                if (isset($seenParts[$part])) {
                    throw new \RuntimeException('Duplicate ODT manifest package part: ' . $part);
                }
                $seenParts[$part] = true;
                if ($part === 'content.xml') {
                    $hasContentXml = true;
                }
            } else {
                $rootMediaType = $mediaType;
            }
            $pathShape = self::manifestPathShape($packageReference['partReference'] ?? $fullPath);
            $packagePathShape = is_string($part) ? self::manifestPathShape($part) : null;
            $rawItems[] = [
                'manifestIndex' => $manifestIndex,
                'fullPath' => $fullPath,
                'part' => $part,
                'partReference' => $packageReference['partReference'],
                'partSuffix' => $packageReference['partSuffix'],
                'partQuery' => $packageReference['partQuery'],
                'partFragment' => $packageReference['partFragment'],
                'pathShape' => $pathShape,
                'packagePathShape' => $packagePathShape,
                'uriEncodedPartReference' => is_string($packageReference['partReference'])
                    && is_string($part)
                    && $packageReference['partReference'] !== $part,
                'mediaType' => $mediaType,
                'mediaTypeBase' => $mediaTypeReport['mediaTypeBase'],
                'mediaTypeHasParameters' => $mediaTypeReport['mediaTypeHasParameters'],
                'mediaTypeParameterCount' => $mediaTypeReport['mediaTypeParameterCount'],
                'mediaTypeParameters' => $mediaTypeReport['mediaTypeParameters'],
                'mediaTypeParameterMap' => $mediaTypeReport['mediaTypeParameterMap'],
                'version' => $version === '' ? null : $version,
                'preferredViewMode' => $preferredViewMode === '' ? null : $preferredViewMode,
                'manifestAttributeCount' => $attributeProvenance['attributeCount'],
                'manifestAttributeNames' => $attributeProvenance['attributeNames'],
                'manifestAttributes' => $attributeProvenance['attributes'],
                'customManifestAttributeCount' => $attributeProvenance['customAttributeCount'],
                'customManifestAttributeNames' => $attributeProvenance['customAttributeNames'],
                'customManifestAttributes' => $attributeProvenance['customAttributes'],
                'customManifestAttributeMap' => $attributeProvenance['customAttributeMap'],
                'manifestNamespaceDeclarationCount' => $attributeProvenance['namespaceDeclarationCount'],
                'manifestNamespaceDeclarationNames' => $attributeProvenance['namespaceDeclarationNames'],
                'manifestNamespaceDeclarations' => $attributeProvenance['namespaceDeclarations'],
                'manifestNamespaceDeclarationMap' => $attributeProvenance['namespaceDeclarationMap'],
                'manifestChildElementCount' => $childElementProvenance['childElementCount'],
                'manifestChildElementNames' => $childElementProvenance['childElementNames'],
                'manifestChildElements' => $childElementProvenance['childElements'],
                'customManifestChildElementCount' => $childElementProvenance['customChildElementCount'],
                'customManifestChildElementNames' => $childElementProvenance['customChildElementNames'],
                'customManifestChildElements' => $childElementProvenance['customChildElements'],
                'declaredSize' => $declaredSize['value'],
                'declaredSizeRaw' => $declaredSize['raw'],
                'declaredSizeValid' => $declaredSize['valid'],
                'declaredSizeInvalid' => $declaredSize['invalid'],
                'encrypted' => $encrypted,
                'encryption' => $encrypted ? $this->encryptionRecords($encryptionElements) : null,
            ];
            ++$manifestIndex;
        }

        if ($rawItems === []) {
            throw new \RuntimeException('ODT manifest does not contain file entries');
        }
        if ($rootMediaType === null) {
            throw new \RuntimeException('ODT manifest is missing root file-entry /');
        }
        if ($rootMediaType !== self::MIMETYPE) {
            throw new \RuntimeException('ODT manifest root entry must declare application/vnd.oasis.opendocument.text');
        }
        if (!$hasContentXml) {
            throw new \RuntimeException('ODT manifest is missing content.xml');
        }

        $items = [];
        $objectPackageRootParts = $this->objectPackageRootParts($rawItems);
        foreach ($rawItems as $rawItem) {
            $part = $rawItem['part'] ?? null;
            $mediaType = (string) ($rawItem['mediaType'] ?? '');
            $isDirectory = is_string($part) && str_ends_with($part, '/');
            $exists = $part === null || $isDirectory || $package->has($part);
            $zipEntry = $exists && is_string($part) && $part !== '' && !$isDirectory ? $package->entry($part) : null;
            $storedByteLength = $zipEntry instanceof ZipPackageEntry ? $zipEntry->uncompressedSize : null;
            $compressionMethod = $zipEntry instanceof ZipPackageEntry ? $zipEntry->compressionMethod : null;
            $hasSupportedCompression = $compressionMethod === null || $compressionMethod === 0 || $compressionMethod === 8;
            $missingFileMediaType = $mediaType === '' && is_string($part) && $part !== '' && !$isDirectory;
            $diagnostics = $missingFileMediaType ? ['odf-manifest-file-entry-missing-media-type'] : [];
            if (($rawItem['declaredSizeInvalid'] ?? false) === true) {
                $diagnostics[] = 'odf-manifest-invalid-declared-size';
            }
            $encrypted = ($rawItem['encrypted'] ?? false) === true;
            $declaredSize = is_int($rawItem['declaredSize'] ?? null) ? $rawItem['declaredSize'] : null;
            $declaredSizeMismatch = !$encrypted
                && $declaredSize !== null
                && $storedByteLength !== null
                && $declaredSize !== $storedByteLength;

            $embeddedObjectPackage = is_string($part) && $part !== ''
                ? $this->embeddedObjectPackageMembership($part, $objectPackageRootParts)
                : null;
            $embeddedObjectPackagePart = is_array($embeddedObjectPackage);
            $thumbnailPackagePart = is_string($part) && $this->isThumbnailPackagePartName($part);
            $scriptPackagePart = is_string($part) && $this->isScriptPackagePartName($part);
            $signaturePackagePart = is_string($part) && $this->isSignaturePartName($part);
            $configurationPackagePart = is_string($part) && self::isConfigurationPackagePartName($part);
            $fontPackagePart = is_string($part) && $this->isFontPackagePart($part, $mediaType);
            $rdfMetadataPart = is_string($part) && $this->isRdfPackagePart($part, $mediaType);
            $objectReplacementPackagePart = is_string($part) && $this->isObjectReplacementPackagePartName($part);
            $layoutCachePackagePart = is_string($part) && $this->isLayoutCachePackagePartName($part);
            $metaInfSidecarPackagePart = is_string($part) && $this->isMetaInfSidecarPackagePartName($part);
            $databasePackagePart = is_string($part) && $this->isDatabasePackagePartName($part);
            $canExposeBytes = !$encrypted
                && !$isDirectory
                && !$embeddedObjectPackagePart
                && !$thumbnailPackagePart
                && !$scriptPackagePart
                && !$signaturePackagePart
                && !$configurationPackagePart
                && !$fontPackagePart
                && !$rdfMetadataPart
                && !$objectReplacementPackagePart
                && !$layoutCachePackagePart
                && !$metaInfSidecarPackagePart
                && !$databasePackagePart
                && !$missingFileMediaType
                && $zipEntry instanceof ZipPackageEntry
                && $hasSupportedCompression;
            $byteExposurePolicy = self::byteExposurePolicy(
                $part,
                $exists,
                $isDirectory,
                $encrypted,
                $embeddedObjectPackagePart,
                $thumbnailPackagePart,
                $scriptPackagePart,
                $signaturePackagePart,
                $configurationPackagePart,
                $fontPackagePart,
                $rdfMetadataPart,
                $objectReplacementPackagePart,
                $layoutCachePackagePart,
                $metaInfSidecarPackagePart,
                $databasePackagePart,
                $missingFileMediaType,
                $hasSupportedCompression
            );
            $item = $rawItem + [
                'exists' => $exists,
                'isDirectory' => $isDirectory,
                'byteLength' => $canExposeBytes && $zipEntry instanceof ZipPackageEntry ? $zipEntry->uncompressedSize : null,
                'storedByteLength' => $storedByteLength,
                'compressedByteLength' => $zipEntry instanceof ZipPackageEntry ? $zipEntry->compressedSize : null,
                'compressionMethod' => $compressionMethod,
                'compressionMethodName' => $compressionMethod !== null ? self::compressionMethodName($compressionMethod) : null,
                'crc32' => $canExposeBytes && $zipEntry instanceof ZipPackageEntry ? $zipEntry->crc32Hex() : null,
                'storedCrc32' => $zipEntry instanceof ZipPackageEntry ? $zipEntry->crc32Hex() : null,
                'byteSha256' => $this->packageEntryByteSha256($package, $part, $canExposeBytes),
                'declaredSizeMismatch' => $declaredSizeMismatch,
                'embeddedObjectPackagePart' => $embeddedObjectPackagePart,
                'embeddedObjectRootPart' => is_array($embeddedObjectPackage) ? $embeddedObjectPackage['rootPart'] : null,
                'embeddedObjectPath' => is_array($embeddedObjectPackage) ? $embeddedObjectPackage['objectPath'] : null,
                'embeddedObjectType' => is_array($embeddedObjectPackage) ? $embeddedObjectPackage['objectType'] : null,
                'embeddedObjectRoot' => is_array($embeddedObjectPackage) && $embeddedObjectPackage['isRoot'] === true,
                'embeddedObjectContainedPart' => is_array($embeddedObjectPackage) && $embeddedObjectPackage['isRoot'] !== true,
                'embeddedObjectMediaType' => is_array($embeddedObjectPackage) ? $embeddedObjectPackage['mediaType'] : null,
                'thumbnailPackagePart' => $thumbnailPackagePart,
                'scriptPackagePart' => $scriptPackagePart,
                'signaturePackagePart' => $signaturePackagePart,
                'configurationPackagePart' => $configurationPackagePart,
                'fontPackagePart' => $fontPackagePart,
                'rdfMetadataPart' => $rdfMetadataPart,
                'objectReplacementPackagePart' => $objectReplacementPackagePart,
                'layoutCachePackagePart' => $layoutCachePackagePart,
                'metaInfSidecarPackagePart' => $metaInfSidecarPackagePart,
                'databasePackagePart' => $databasePackagePart,
                'canExposeBytes' => $canExposeBytes,
                'byteExposurePolicy' => $byteExposurePolicy,
                'missingMediaType' => $missingFileMediaType,
            ];
            if ($diagnostics !== []) {
                $item['diagnostics'] = $diagnostics;
            }
            $items[] = $item;
        }

        return $items;
    }

    /**
     * @return array{
     *     attributeCount:int,
     *     attributeNames:list<string>,
     *     attributes:list<array<string, mixed>>,
     *     customAttributeCount:int,
     *     customAttributeNames:list<string>,
     *     customAttributes:list<array<string, mixed>>,
     *     customAttributeMap:array<string, string>,
     *     namespaceDeclarationCount:int,
     *     namespaceDeclarationNames:list<string>,
     *     namespaceDeclarations:list<array<string, mixed>>,
     *     namespaceDeclarationMap:array<string, string>
     * }
     */
    private function manifestFileEntryAttributeProvenance(\DOMElement $element): array
    {
        return $this->manifestElementAttributeProvenance($element, self::MANIFEST_FILE_ENTRY_STRUCTURAL_ATTRIBUTES);
    }

    /**
     * @return array{
     *     attributeCount:int,
     *     attributeNames:list<string>,
     *     attributes:list<array<string, mixed>>,
     *     customAttributeCount:int,
     *     customAttributeNames:list<string>,
     *     customAttributes:list<array<string, mixed>>,
     *     customAttributeMap:array<string, string>,
     *     namespaceDeclarationCount:int,
     *     namespaceDeclarationNames:list<string>,
     *     namespaceDeclarations:list<array<string, mixed>>,
     *     namespaceDeclarationMap:array<string, string>
     * }
     */
    private function manifestRootAttributeProvenance(\DOMElement $element): array
    {
        return $this->manifestElementAttributeProvenance($element, self::MANIFEST_ROOT_STRUCTURAL_ATTRIBUTES);
    }

    /**
     * @return array{
     *     extensionElementCount:int,
     *     extensionElementNames:list<string>,
     *     extensionElements:list<array<string, mixed>>
     * }
     */
    private function manifestRootExtensionElementProvenance(\DOMElement $element): array
    {
        $extensionElements = [];

        foreach (self::childElements($element) as $child) {
            if ($child->namespaceURI === self::MANIFEST_NS && $child->localName === 'file-entry') {
                continue;
            }
            if ($child->namespaceURI === self::MANIFEST_NS) {
                throw new \InvalidArgumentException('ODT manifest may only contain manifest:file-entry children in the manifest namespace');
            }

            $extensionElements[] = $this->manifestChildElementRecord($child, false);
        }

        return [
            'extensionElementCount' => count($extensionElements),
            'extensionElementNames' => array_values(array_map(static fn (array $item): string => $item['name'], $extensionElements)),
            'extensionElements' => $extensionElements,
        ];
    }

    /**
     * @return array{
     *     childElementCount:int,
     *     childElementNames:list<string>,
     *     childElements:list<array<string, mixed>>,
     *     customChildElementCount:int,
     *     customChildElementNames:list<string>,
     *     customChildElements:list<array<string, mixed>>
     * }
     */
    private function manifestFileEntryChildElementProvenance(\DOMElement $element): array
    {
        $childElements = [];
        $customChildElements = [];

        foreach (self::childElements($element) as $child) {
            $namespaceUri = (string) $child->namespaceURI;
            $structural = $namespaceUri === self::MANIFEST_NS
                && isset(self::MANIFEST_FILE_ENTRY_STRUCTURAL_CHILD_ELEMENTS[$child->localName]);
            $record = $this->manifestChildElementRecord($child, $structural);

            $childElements[] = $record;
            if (!$structural) {
                $customChildElements[] = $record;
            }
        }

        return [
            'childElementCount' => count($childElements),
            'childElementNames' => array_values(array_map(static fn (array $item): string => $item['name'], $childElements)),
            'childElements' => $childElements,
            'customChildElementCount' => count($customChildElements),
            'customChildElementNames' => array_values(array_map(static fn (array $item): string => $item['name'], $customChildElements)),
            'customChildElements' => $customChildElements,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function manifestChildElementRecord(\DOMElement $child, bool $structural): array
    {
        $record = [
            'name' => $this->qualifiedElementName($child),
            'localName' => $child->localName,
            'structural' => $structural,
            'attributeCount' => $child->hasAttributes() ? $child->attributes->length : 0,
            'childElementCount' => count(self::childElements($child)),
        ];
        $namespaceUri = (string) $child->namespaceURI;
        if ($namespaceUri !== '') {
            $record['namespaceUri'] = $namespaceUri;
        }
        if ($child->prefix !== '') {
            $record['prefix'] = $child->prefix;
        }

        return $record;
    }

    /**
     * @return array{
     *     attributeCount:int,
     *     attributeNames:list<string>,
     *     attributes:list<array<string, mixed>>,
     *     customAttributeCount:int,
     *     customAttributeNames:list<string>,
     *     customAttributes:list<array<string, mixed>>,
     *     customAttributeMap:array<string, string>,
     *     namespaceDeclarationCount:int,
     *     namespaceDeclarationNames:list<string>,
     *     namespaceDeclarations:list<array<string, mixed>>,
     *     namespaceDeclarationMap:array<string, string>
     * }
     */
    private function documentPartRootAttributeProvenance(\DOMElement $element): array
    {
        return $this->manifestElementAttributeProvenance(
            $element,
            self::OFFICE_DOCUMENT_ROOT_STRUCTURAL_ATTRIBUTES,
            self::OFFICE_NS
        );
    }

    /**
     * @param array<string, bool> $structuralAttributes
     * @return array{
     *     attributeCount:int,
     *     attributeNames:list<string>,
     *     attributes:list<array<string, mixed>>,
     *     customAttributeCount:int,
     *     customAttributeNames:list<string>,
     *     customAttributes:list<array<string, mixed>>,
     *     customAttributeMap:array<string, string>,
     *     namespaceDeclarationCount:int,
     *     namespaceDeclarationNames:list<string>,
     *     namespaceDeclarations:list<array<string, mixed>>,
     *     namespaceDeclarationMap:array<string, string>
     * }
     */
    private function manifestElementAttributeProvenance(
        \DOMElement $element,
        array $structuralAttributes,
        string $structuralNamespace = self::MANIFEST_NS
    ): array {
        $attributes = [];
        $customAttributes = [];
        $customAttributeMap = [];
        $namespaceDeclarations = $this->manifestElementNamespaceDeclarations($element);
        $namespaceDeclarationMap = array_map(
            static fn (array $declaration): string => $declaration['namespaceUri'],
            $namespaceDeclarations
        );
        if ($element->hasAttributes()) {
            foreach ($element->attributes as $attribute) {
                if (!$attribute instanceof \DOMAttr) {
                    continue;
                }

                if ($attribute->prefix !== '' && is_string($attribute->namespaceURI) && $attribute->namespaceURI !== '' && $attribute->prefix !== 'xmlns') {
                    $namespaceName = 'xmlns:' . $attribute->prefix;
                    if (!isset($namespaceDeclarations[$namespaceName])) {
                        $namespaceDeclarations[$namespaceName] = [
                            'name' => $namespaceName,
                            'declaredPrefix' => $attribute->prefix,
                            'namespaceUri' => $attribute->namespaceURI,
                            'default' => false,
                        ];
                        $namespaceDeclarationMap[$namespaceName] = $attribute->namespaceURI;
                    }
                }

                if ($attribute->namespaceURI === self::XMLNS_NS) {
                    $name = $attribute->name === 'xmlns'
                        ? 'xmlns'
                        : 'xmlns:' . $attribute->localName;
                    $declaredPrefix = $attribute->name === 'xmlns' ? '' : $attribute->localName;
                    $namespaceDeclarations[$name] = [
                        'name' => $name,
                        'declaredPrefix' => $declaredPrefix,
                        'namespaceUri' => $attribute->value,
                        'default' => $declaredPrefix === '',
                    ];
                    $namespaceDeclarationMap[$name] = $attribute->value;
                    continue;
                }

                $name = $attribute->prefix !== ''
                    ? $attribute->prefix . ':' . $attribute->localName
                    : $attribute->name;
                $structural = $attribute->namespaceURI === $structuralNamespace
                    && isset($structuralAttributes[$attribute->localName]);
                $record = [
                    'name' => $name,
                    'localName' => $attribute->localName,
                    'value' => $attribute->value,
                    'structural' => $structural,
                ];
                $namespaceUri = (string) $attribute->namespaceURI;
                if ($namespaceUri !== '') {
                    $record['namespaceUri'] = $namespaceUri;
                }
                if ($attribute->prefix !== '') {
                    $record['prefix'] = $attribute->prefix;
                }

                $attributes[$name] = $record;
                if (!$structural) {
                    $customAttributes[$name] = $record;
                    $customAttributeMap[$name] = $attribute->value;
                }
            }
        }

        ksort($attributes, SORT_STRING);
        ksort($customAttributes, SORT_STRING);
        ksort($customAttributeMap, SORT_STRING);
        ksort($namespaceDeclarations, SORT_STRING);
        ksort($namespaceDeclarationMap, SORT_STRING);

        return [
            'attributeCount' => count($attributes),
            'attributeNames' => array_keys($attributes),
            'attributes' => array_values($attributes),
            'customAttributeCount' => count($customAttributes),
            'customAttributeNames' => array_keys($customAttributes),
            'customAttributes' => array_values($customAttributes),
            'customAttributeMap' => $customAttributeMap,
            'namespaceDeclarationCount' => count($namespaceDeclarations),
            'namespaceDeclarationNames' => array_keys($namespaceDeclarations),
            'namespaceDeclarations' => array_values($namespaceDeclarations),
            'namespaceDeclarationMap' => $namespaceDeclarationMap,
        ];
    }

    /**
     * @return array<string, array{name:string, declaredPrefix:string, namespaceUri:string, default:bool}>
     */
    private function manifestElementNamespaceDeclarations(\DOMElement $element): array
    {
        $xpath = new \DOMXPath($element->ownerDocument);
        $nodes = $xpath->query('namespace::*', $element);
        if ($nodes === false) {
            return [];
        }

        $declarations = [];
        foreach ($nodes as $node) {
            if (!$node instanceof \DOMNameSpaceNode || $node->nodeName === 'xmlns:xml') {
                continue;
            }

            $name = $node->nodeName;
            $declaredPrefix = $name === 'xmlns' ? '' : $node->localName;
            $declarations[$name] = [
                'name' => $name,
                'declaredPrefix' => $declaredPrefix,
                'namespaceUri' => (string) $node->nodeValue,
                'default' => $declaredPrefix === '',
            ];
        }

        ksort($declarations, SORT_STRING);

        return $declarations;
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @return array<string, mixed>
     */
    private function documentPartVersionMetadata(ZipPackage $package, array $manifest): array
    {
        $manifestByPart = $this->manifestByPart($manifest);
        $expectedRoots = [
            'content.xml' => 'document-content',
            'styles.xml' => 'document-styles',
            'meta.xml' => 'document-meta',
            'settings.xml' => 'document-settings',
        ];
        $manifestVersion = $this->manifestVersion === '' ? null : $this->manifestVersion;
        $items = [];
        $versionCounts = [];
        $missingVersionParts = [];
        $versionMismatches = [];
        $rootCustomAttributeCount = 0;
        $rootCustomAttributeNames = [];
        $rootCustomAttributeItems = [];

        foreach ($expectedRoots as $part => $expectedRoot) {
            $manifestItem = $manifestByPart[$part] ?? null;
            if (!$package->has($part) && !is_array($manifestItem)) {
                continue;
            }

            $entry = $package->has($part) ? $package->entry($part) : null;
            $rootName = null;
            $officeVersion = null;
            $validRoot = false;
            $diagnostics = [];
            $rootAttributeProvenance = [
                'attributeCount' => 0,
                'attributeNames' => [],
                'attributes' => [],
                'customAttributeCount' => 0,
                'customAttributeNames' => [],
                'customAttributes' => [],
                'customAttributeMap' => [],
                'namespaceDeclarationCount' => 0,
                'namespaceDeclarationNames' => [],
                'namespaceDeclarations' => [],
                'namespaceDeclarationMap' => [],
            ];

            if (!$entry instanceof ZipPackageEntry) {
                $diagnostics[] = 'odf-xml-part-missing-package-part';
            } else {
                $dom = self::loadXml($package->read($part), 'ODT ' . $part);
                $root = $dom->documentElement;
                if ($root instanceof \DOMElement) {
                    $rootName = $root->localName;
                    $validRoot = $root->namespaceURI === self::OFFICE_NS && $root->localName === $expectedRoot;
                    $officeVersion = self::nullable(self::attr($root, self::OFFICE_NS, 'version'));
                    $rootAttributeProvenance = $this->documentPartRootAttributeProvenance($root);
                }

                if (!$validRoot) {
                    $diagnostics[] = 'odf-xml-part-unexpected-root';
                }
                if ($officeVersion === null) {
                    $diagnostics[] = 'odf-xml-part-missing-office-version';
                    $missingVersionParts[] = $part;
                } else {
                    $versionCounts[$officeVersion] = ($versionCounts[$officeVersion] ?? 0) + 1;
                    if ($manifestVersion !== null && $officeVersion !== $manifestVersion) {
                        $diagnostics[] = 'odf-xml-part-version-mismatch';
                        $versionMismatches[] = [
                            'part' => $part,
                            'officeVersion' => $officeVersion,
                            'manifestVersion' => $manifestVersion,
                        ];
                    }
                }
            }

            if (!is_array($manifestItem)) {
                $diagnostics[] = 'odf-xml-part-undeclared-package-part';
            }

            $partCustomAttributeCount = (int) ($rootAttributeProvenance['customAttributeCount'] ?? 0);
            if ($partCustomAttributeCount > 0) {
                $rootCustomAttributeCount += $partCustomAttributeCount;
                foreach ($rootAttributeProvenance['customAttributeNames'] ?? [] as $attributeName) {
                    if (is_string($attributeName) && $attributeName !== '' && !in_array($attributeName, $rootCustomAttributeNames, true)) {
                        $rootCustomAttributeNames[] = $attributeName;
                    }
                }
                $rootCustomAttributeItems[] = [
                    'part' => $part,
                    'expectedRoot' => $expectedRoot,
                    'rootName' => $rootName,
                    'rootCustomAttributeCount' => $partCustomAttributeCount,
                    'rootCustomAttributeNames' => $rootAttributeProvenance['customAttributeNames'] ?? [],
                    'rootCustomAttributes' => $rootAttributeProvenance['customAttributes'] ?? [],
                    'rootCustomAttributeMap' => $rootAttributeProvenance['customAttributeMap'] ?? [],
                    'rootNamespaceDeclarationCount' => $rootAttributeProvenance['namespaceDeclarationCount'] ?? 0,
                    'rootNamespaceDeclarationNames' => $rootAttributeProvenance['namespaceDeclarationNames'] ?? [],
                    'rootNamespaceDeclarations' => $rootAttributeProvenance['namespaceDeclarations'] ?? [],
                    'rootNamespaceDeclarationMap' => $rootAttributeProvenance['namespaceDeclarationMap'] ?? [],
                ];
            }

            $items[] = [
                'part' => $part,
                'expectedRoot' => $expectedRoot,
                'rootName' => $rootName,
                'validRoot' => $validRoot,
                'officeVersion' => $officeVersion,
                'rootAttributeCount' => $rootAttributeProvenance['attributeCount'] ?? 0,
                'rootAttributeNames' => $rootAttributeProvenance['attributeNames'] ?? [],
                'rootAttributes' => $rootAttributeProvenance['attributes'] ?? [],
                'rootCustomAttributeCount' => $rootAttributeProvenance['customAttributeCount'] ?? 0,
                'rootCustomAttributeNames' => $rootAttributeProvenance['customAttributeNames'] ?? [],
                'rootCustomAttributes' => $rootAttributeProvenance['customAttributes'] ?? [],
                'rootCustomAttributeMap' => $rootAttributeProvenance['customAttributeMap'] ?? [],
                'rootNamespaceDeclarationCount' => $rootAttributeProvenance['namespaceDeclarationCount'] ?? 0,
                'rootNamespaceDeclarationNames' => $rootAttributeProvenance['namespaceDeclarationNames'] ?? [],
                'rootNamespaceDeclarations' => $rootAttributeProvenance['namespaceDeclarations'] ?? [],
                'rootNamespaceDeclarationMap' => $rootAttributeProvenance['namespaceDeclarationMap'] ?? [],
                'manifestVersion' => $manifestVersion,
                'declaredInManifest' => is_array($manifestItem),
                'manifestFullPath' => is_array($manifestItem) ? $manifestItem['fullPath'] : null,
                'manifestMediaType' => is_array($manifestItem) ? $manifestItem['mediaType'] : null,
                'exists' => $entry instanceof ZipPackageEntry,
                'byteLength' => $entry instanceof ZipPackageEntry ? $entry->uncompressedSize : null,
                'compressedByteLength' => $entry instanceof ZipPackageEntry ? $entry->compressedSize : null,
                'compressionMethod' => $entry instanceof ZipPackageEntry ? $entry->compressionMethod : null,
                'compressionMethodName' => $entry instanceof ZipPackageEntry ? self::compressionMethodName($entry->compressionMethod) : null,
                'crc32' => $entry instanceof ZipPackageEntry ? $entry->crc32Hex() : null,
                'diagnostics' => array_values(array_unique($diagnostics)),
            ];
        }

        ksort($versionCounts, SORT_STRING);
        sort($rootCustomAttributeNames, SORT_STRING);

        return [
            'count' => count($items),
            'versionedCount' => array_sum($versionCounts),
            'missingVersionCount' => count($missingVersionParts),
            'missingVersionParts' => $missingVersionParts,
            'versionMismatchCount' => count($versionMismatches),
            'versionMismatches' => $versionMismatches,
            'manifestVersion' => $manifestVersion,
            'versionCounts' => $versionCounts,
            'rootCustomAttributePartCount' => count($rootCustomAttributeItems),
            'rootCustomAttributeCount' => $rootCustomAttributeCount,
            'rootCustomAttributeNames' => $rootCustomAttributeNames,
            'rootCustomAttributeItems' => $rootCustomAttributeItems,
            'items' => $items,
        ];
    }

    /**
     * @param list<\DOMElement> $elements
     * @return array<string, mixed>
     */
    private function encryptionRecords(array $elements): array
    {
        $records = array_map(
            fn (\DOMElement $element): array => $this->encryptionData($element),
            $elements
        );
        $data = $records[0] ?? [];
        $data['records'] = $records;
        $data['recordCount'] = count($records);

        if (count($records) > 1) {
            $issueCodes = is_array($data['issueCodes'] ?? null) ? $data['issueCodes'] : [];
            $issueCodes[] = 'odf-manifest-encryption-multiple-encryption-data';
            $issueCodes = array_values(array_unique($issueCodes));
            $data['issueCodes'] = $issueCodes;
            $data['issueCount'] = count($issueCodes);
        }

        return self::withoutEmpty($data);
    }

    /**
     * @return array<string, mixed>
     */
    private function encryptionData(\DOMElement $element): array
    {
        $data = self::withoutEmpty([
            'checksumType' => self::nullable(self::attr($element, self::MANIFEST_NS, 'checksum-type')),
            'checksum' => self::nullable(self::attr($element, self::MANIFEST_NS, 'checksum')),
        ]);

        $algorithms = array_map(
            fn (\DOMElement $algorithm): array => $this->encryptionAlgorithmData($algorithm),
            self::childElements($element, 'algorithm', self::MANIFEST_NS)
        );
        if ($algorithms !== []) {
            $data['algorithm'] = $algorithms[0];
            $data['algorithms'] = $algorithms;
            $data['algorithmCount'] = count($algorithms);
        }

        $keyDerivations = array_map(
            fn (\DOMElement $keyDerivation): array => $this->encryptionKeyDerivationData($keyDerivation),
            self::childElements($element, 'key-derivation', self::MANIFEST_NS)
        );
        if ($keyDerivations !== []) {
            $data['keyDerivation'] = $keyDerivations[0];
            $data['keyDerivations'] = $keyDerivations;
            $data['keyDerivationCount'] = count($keyDerivations);
        }

        $startKeyGenerations = array_map(
            fn (\DOMElement $startKeyGeneration): array => $this->encryptionStartKeyGenerationData($startKeyGeneration),
            self::childElements($element, 'start-key-generation', self::MANIFEST_NS)
        );
        if ($startKeyGenerations !== []) {
            $data['startKeyGeneration'] = $startKeyGenerations[0];
            $data['startKeyGenerations'] = $startKeyGenerations;
            $data['startKeyGenerationCount'] = count($startKeyGenerations);
        }

        $unknownChildren = $this->encryptionUnknownChildren($element);
        if ($unknownChildren !== []) {
            $data['unknownChildCount'] = count($unknownChildren);
            $data['unknownChildren'] = $unknownChildren;
        }

        $issueCodes = [];
        if (count($algorithms) > 1) {
            $issueCodes[] = 'odf-manifest-encryption-multiple-algorithms';
        }
        if (count($keyDerivations) > 1) {
            $issueCodes[] = 'odf-manifest-encryption-multiple-key-derivations';
        }
        if (count($startKeyGenerations) > 1) {
            $issueCodes[] = 'odf-manifest-encryption-multiple-start-key-generations';
        }
        if ($unknownChildren !== []) {
            $issueCodes[] = 'odf-manifest-encryption-unknown-child';
        }
        if ($issueCodes !== []) {
            $data['issueCount'] = count($issueCodes);
            $data['issueCodes'] = $issueCodes;
        }

        return self::withoutEmpty($data);
    }

    /**
     * @return array<string, mixed>
     */
    private function encryptionAlgorithmData(\DOMElement $algorithm): array
    {
        $initialisationVector = self::attr($algorithm, self::MANIFEST_NS, 'initialisation-vector');
        if ($initialisationVector === '') {
            $initialisationVector = self::attr($algorithm, self::MANIFEST_NS, 'initialization-vector');
        }

        return self::withoutEmpty([
            'name' => self::nullable(self::attr($algorithm, self::MANIFEST_NS, 'algorithm-name')),
            'initialisationVector' => self::nullable($initialisationVector),
        ]);
    }

    /**
     * @return array<string, mixed>
     */
    private function encryptionKeyDerivationData(\DOMElement $keyDerivation): array
    {
        return self::withoutEmpty([
            'name' => self::nullable(self::attr($keyDerivation, self::MANIFEST_NS, 'key-derivation-name')),
            'keySize' => self::nullableInt(self::attr($keyDerivation, self::MANIFEST_NS, 'key-size')),
            'iterationCount' => self::nullableInt(self::attr($keyDerivation, self::MANIFEST_NS, 'iteration-count')),
            'salt' => self::nullable(self::attr($keyDerivation, self::MANIFEST_NS, 'salt')),
        ]);
    }

    /**
     * @return array<string, mixed>
     */
    private function encryptionStartKeyGenerationData(\DOMElement $startKeyGeneration): array
    {
        return self::withoutEmpty([
            'name' => self::nullable(self::attr($startKeyGeneration, self::MANIFEST_NS, 'start-key-generation-name')),
            'keySize' => self::nullableInt(self::attr($startKeyGeneration, self::MANIFEST_NS, 'key-size')),
        ]);
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function encryptionUnknownChildren(\DOMElement $element): array
    {
        $unknownChildren = [];
        foreach (self::childElements($element) as $child) {
            if (
                $child->namespaceURI === self::MANIFEST_NS
                && in_array($child->localName, ['algorithm', 'key-derivation', 'start-key-generation'], true)
            ) {
                continue;
            }

            $unknownChildren[] = self::withoutEmpty([
                'name' => $this->qualifiedElementName($child),
                'namespaceUri' => self::nullable((string) $child->namespaceURI),
                'localName' => $child->localName,
            ]);
        }

        return $unknownChildren;
    }

    private function qualifiedElementName(\DOMElement $element): string
    {
        return $element->prefix === '' ? $element->localName : $element->prefix . ':' . $element->localName;
    }

    private static function compressionMethodName(int $method): string
    {
        return match ($method) {
            0 => 'stored',
            8 => 'deflated',
            default => 'unsupported',
        };
    }

    private static function byteExposurePolicy(
        ?string $part,
        bool $exists,
        bool $isDirectory,
        bool $encrypted,
        bool $embeddedObjectPackagePart,
        bool $thumbnailPackagePart,
        bool $scriptPackagePart,
        bool $signaturePackagePart,
        bool $configurationPackagePart,
        bool $fontPackagePart,
        bool $rdfMetadataPart,
        bool $objectReplacementPackagePart,
        bool $layoutCachePackagePart,
        bool $metaInfSidecarPackagePart,
        bool $databasePackagePart,
        bool $missingFileMediaType,
        bool $hasSupportedCompression
    ): string {
        if ($part === null) {
            return 'package-root-no-bytes';
        }
        if ($isDirectory) {
            return 'directory-entry-no-bytes';
        }
        if ($encrypted) {
            return 'encrypted-resource-bytes-blocked';
        }
        if ($embeddedObjectPackagePart) {
            return 'embedded-object-package-bytes-blocked';
        }
        if ($thumbnailPackagePart) {
            return 'package-thumbnail-bytes-blocked';
        }
        if ($scriptPackagePart) {
            return 'script-package-bytes-blocked';
        }
        if ($signaturePackagePart) {
            return 'signature-package-bytes-blocked';
        }
        if ($configurationPackagePart) {
            return 'configuration-package-bytes-blocked';
        }
        if ($fontPackagePart) {
            return 'font-package-bytes-blocked';
        }
        if ($rdfMetadataPart) {
            return 'rdf-metadata-bytes-blocked';
        }
        if ($objectReplacementPackagePart) {
            return 'object-replacement-package-bytes-blocked';
        }
        if ($layoutCachePackagePart) {
            return 'layout-cache-package-bytes-blocked';
        }
        if ($metaInfSidecarPackagePart) {
            return 'meta-inf-sidecar-package-bytes-blocked';
        }
        if ($databasePackagePart) {
            return 'database-package-bytes-blocked';
        }
        if ($missingFileMediaType) {
            return 'missing-media-type-bytes-blocked';
        }
        if (!$hasSupportedCompression) {
            return 'unsupported-compression-bytes-blocked';
        }

        return $exists ? 'package-bytes-exposable' : 'missing-package-part';
    }

