        }

        return self::withoutEmpty([
            'type' => 'range',
            'element' => 'named-range',
            'name' => $name,
            'cellRangeAddress' => self::nullable(self::attr($range, self::TABLE_NS, 'cell-range-address')),
            'baseCellAddress' => self::nullable(self::attr($range, self::TABLE_NS, 'base-cell-address')),
