    private function isObjectReplacementPackagePartName(string $part): bool
    {
        $normalized = strtolower(ltrim($part, '/'));
        if (str_ends_with($normalized, '/')) {
            return false;
        }

        return str_starts_with($normalized, 'objectreplacements/');
    }

    private function objectReplacementMediaTypeFromPart(string $part): ?string
    {
        return $this->thumbnailMediaTypeFromPart($part);
    }

    private function isObjectReplacementMediaType(string $mediaType): bool
    {
        return str_starts_with(self::mediaTypeReport($mediaType)['mediaTypeBase'], 'image/');
    }

    private function isLayoutCachePackagePartName(string $part): bool
    {
        return strtolower(ltrim($part, '/')) === 'layout-cache';
    }

    private function isMetaInfSidecarPackagePartName(string $part): bool
    {
        $normalized = strtolower(ltrim($part, '/'));
        if (
            $normalized === 'meta-inf/manifest.xml'
            || str_ends_with($normalized, '/')
            || $this->isSignaturePartName($part)
        ) {
            return false;
        }

        return str_starts_with($normalized, 'meta-inf/');
    }

    private function isDatabasePackagePartName(string $part): bool
    {
        $normalized = strtolower(ltrim($part, '/'));
        if (str_ends_with($normalized, '/')) {
            return false;
        }

        return str_starts_with($normalized, 'database/');
    }

    private function layoutCacheMediaTypeFromPart(string $part): string
    {
        return $this->isLayoutCachePackagePartName($part) ? 'application/binary' : '';
    }

    private function isLayoutCacheMediaType(string $mediaType): bool
    {
        return in_array(self::mediaTypeReport($mediaType)['mediaTypeBase'], ['application/binary', 'application/octet-stream'], true);
    }

    private function isXmlMediaType(string $mediaType): bool
    {
        $base = self::mediaTypeReport($mediaType)['mediaTypeBase'];

        return $base === 'text/xml'
            || $base === 'application/xml'
            || str_ends_with($base, '+xml');
    }

    /**
     * @return array{mediaType:string, mediaTypeBase:string, mediaTypeHasParameters:bool, mediaTypeParameterCount:int, mediaTypeParameters:list<array{name:string, value:string, raw:string}>, mediaTypeParameterMap:array<string, string>}
     */
    private static function mediaTypeReport(string $mediaType): array
    {
        $segments = self::mediaTypeSegments($mediaType);
        $base = strtolower(trim((string) array_shift($segments)));
        $parameters = [];
        $parameterMap = [];

        foreach ($segments as $segment) {
            $raw = trim($segment);
            if ($raw === '') {
                continue;
            }

            $equals = strpos($raw, '=');
            $name = $equals === false ? strtolower(trim($raw)) : strtolower(trim(substr($raw, 0, $equals)));
            if ($name === '') {
                continue;
            }

            $value = $equals === false ? '' : trim(substr($raw, $equals + 1));
            if (strlen($value) >= 2 && $value[0] === '"' && substr($value, -1) === '"') {
                $value = substr($value, 1, -1);
                $value = preg_replace('/\\\\([\x20-\x7E])/', '$1', $value) ?? $value;
            }

            $parameters[] = [
                'name' => $name,
                'value' => $value,
                'raw' => $raw,
            ];
            $parameterMap[$name] = $value;
        }

        return [
            'mediaType' => $mediaType,
            'mediaTypeBase' => $base,
            'mediaTypeHasParameters' => $parameters !== [],
            'mediaTypeParameterCount' => count($parameters),
            'mediaTypeParameters' => $parameters,
            'mediaTypeParameterMap' => $parameterMap,
        ];
    }

    /**
     * @return list<string>
     */
    private static function mediaTypeSegments(string $mediaType): array
    {
        $segments = [];
        $current = '';
        $inQuote = false;
        $escaped = false;
        $length = strlen($mediaType);

        for ($index = 0; $index < $length; $index++) {
            $char = $mediaType[$index];
            if ($escaped) {
                $current .= $char;
                $escaped = false;
                continue;
            }

            if ($inQuote && $char === '\\') {
                $current .= $char;
                $escaped = true;
                continue;
            }

            if ($char === '"') {
                $inQuote = !$inQuote;
                $current .= $char;
                continue;
            }

            if ($char === ';' && !$inQuote) {
                $segments[] = $current;
                $current = '';
                continue;
            }

            $current .= $char;
        }

        $segments[] = $current;

        return $segments;
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @return array<string, array<string, mixed>>
     */
    private function manifestByPart(array $manifest): array
    {
        $byPart = [];
        foreach ($manifest as $item) {
            $part = $item['part'] ?? null;
            if (is_string($part) && $part !== '') {
                $byPart[$part] = $item;
            }
        }

        return $byPart;
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @return list<array<string, mixed>>
     */
    private function encryptedManifestItems(array $manifest): array
    {
        return array_values(array_filter(
            $manifest,
            static fn (array $item): bool => ($item['encrypted'] ?? false) === true
        ));
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @return list<array<string, mixed>>
     */
    private function manifestDirectoryItems(array $manifest): array
    {
        return array_values(array_filter(
            $manifest,
            static fn (array $item): bool => ($item['isDirectory'] ?? false) === true
        ));
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @return array<string, mixed>
     */
    private function manifestMediaTypeSummary(array $manifest): array
    {
        $groups = [];
        $groupOrder = [];
        $emptyMediaTypeParts = [];
        $emptyMediaTypeDirectoryParts = [];
        $emptyMediaTypeNonDirectoryItems = [];
        $invalidDeclaredSizeItems = [];
        $parameterValueRecords = [];
        $groupParameterValueRecords = [];
        $diagnostics = [];
        $summary = [
            'manifestItemCount' => count($manifest),
            'typedItemCount' => 0,
            'mediaTypeCount' => 0,
            'emptyMediaTypeCount' => 0,
            'emptyMediaTypeParts' => [],
            'emptyMediaTypeDirectoryCount' => 0,
            'emptyMediaTypeDirectoryParts' => [],
            'emptyMediaTypeNonDirectoryCount' => 0,
            'emptyMediaTypeNonDirectoryItems' => [],
            'diagnosticCount' => 0,
            'diagnosticCodeCounts' => [],
            'diagnostics' => [],
            'directoryCount' => 0,
            'missingCount' => 0,
            'encryptedCount' => 0,
            'versionedItemCount' => 0,
            'manifestVersions' => [],
            'versionedItems' => [],
            'preferredViewModeCount' => 0,
            'preferredViewModes' => [],
            'preferredViewModeItems' => [],
            'declaredSizeMismatchCount' => 0,
            'invalidDeclaredSizeCount' => 0,
            'invalidDeclaredSizeItems' => [],
            'parameterizedItemCount' => 0,
            'mediaTypeParameterNames' => [],
            'mediaTypeParameterValueCount' => 0,
            'mediaTypeParameterValuesByName' => [],
            'mediaTypeParameterValueCounts' => [],
            'mediaTypeParameterValueSummaries' => [],
            'storedByteLength' => 0,
            'compressedByteLength' => 0,
            'exposableByteLength' => 0,
            'declaredSize' => 0,
            'storedCompressionMethodCount' => 0,
            'deflatedCompressionMethodCount' => 0,
            'unsupportedCompressionMethodCount' => 0,
            'items' => [],
        ];

        foreach ($manifest as $item) {
            $part = self::manifestItemPartLabel($item);
            $mediaType = trim((string) ($item['mediaType'] ?? ''));
            $mediaTypeReport = self::mediaTypeReport($mediaType);
            $mediaTypeBase = (string) ($item['mediaTypeBase'] ?? $mediaTypeReport['mediaTypeBase']);
            $mediaTypeParameters = is_array($item['mediaTypeParameters'] ?? null)
                ? $item['mediaTypeParameters']
                : $mediaTypeReport['mediaTypeParameters'];
            $exists = ($item['exists'] ?? false) === true;
            $isDirectory = ($item['isDirectory'] ?? false) === true;
            $encrypted = ($item['encrypted'] ?? false) === true;
            $declaredSizeMismatch = ($item['declaredSizeMismatch'] ?? false) === true;
            $declaredSizeInvalid = ($item['declaredSizeInvalid'] ?? false) === true;
            $byteLength = $item['byteLength'] ?? null;
            $storedByteLength = $item['storedByteLength'] ?? null;
            $compressedByteLength = $item['compressedByteLength'] ?? null;
            $declaredSize = $item['declaredSize'] ?? null;
            $compressionMethod = $item['compressionMethod'] ?? null;
            $itemDiagnostics = is_array($item['diagnostics'] ?? null) ? $item['diagnostics'] : [];
            $manifestVersion = trim((string) ($item['version'] ?? ''));
            $preferredViewMode = trim((string) ($item['preferredViewMode'] ?? ''));

            if ($isDirectory) {
                ++$summary['directoryCount'];
            }
            if (!$exists) {
                ++$summary['missingCount'];
            }
            if ($encrypted) {
                ++$summary['encryptedCount'];
            }
            if ($declaredSizeMismatch) {
                ++$summary['declaredSizeMismatchCount'];
            }
            if ($declaredSizeInvalid) {
                ++$summary['invalidDeclaredSizeCount'];
                $invalidDeclaredSizeItems[] = self::withoutEmpty([
                    'fullPath' => $item['fullPath'] ?? null,
                    'part' => $item['part'] ?? null,
                    'mediaType' => $mediaType,
                    'declaredSizeRaw' => $item['declaredSizeRaw'] ?? null,
                    'exists' => $exists,
                    'isDirectory' => $isDirectory,
                    'canExposeBytes' => ($item['canExposeBytes'] ?? false) === true,
                    'diagnostics' => $itemDiagnostics,
                ]);
            }
            if ($manifestVersion !== '') {
                ++$summary['versionedItemCount'];
                if (!in_array($manifestVersion, $summary['manifestVersions'], true)) {
                    $summary['manifestVersions'][] = $manifestVersion;
                }
                $summary['versionedItems'][] = self::withoutEmpty([
                    'fullPath' => $item['fullPath'] ?? null,
                    'part' => $item['part'] ?? null,
                    'mediaType' => $mediaType,
                    'version' => $manifestVersion,
                    'exists' => $exists,
                    'isDirectory' => $isDirectory,
                ]);
            }
            if ($preferredViewMode !== '') {
                ++$summary['preferredViewModeCount'];
                if (!in_array($preferredViewMode, $summary['preferredViewModes'], true)) {
                    $summary['preferredViewModes'][] = $preferredViewMode;
                }
                $summary['preferredViewModeItems'][] = self::withoutEmpty([
                    'fullPath' => $item['fullPath'] ?? null,
                    'part' => $item['part'] ?? null,
                    'mediaType' => $mediaType,
                    'preferredViewMode' => $preferredViewMode,
                    'exists' => $exists,
                    'isDirectory' => $isDirectory,
                ]);
            }
            if (is_int($storedByteLength)) {
                $summary['storedByteLength'] += $storedByteLength;
            }
            if (is_int($byteLength) && ($item['canExposeBytes'] ?? false) === true) {
                $summary['exposableByteLength'] += $byteLength;
            }
            if (is_int($compressedByteLength)) {
                $summary['compressedByteLength'] += $compressedByteLength;
            }
            if (is_int($declaredSize)) {
                $summary['declaredSize'] += $declaredSize;
            }
            if ($compressionMethod === 0) {
                ++$summary['storedCompressionMethodCount'];
            } elseif ($compressionMethod === 8) {
                ++$summary['deflatedCompressionMethodCount'];
            } elseif (is_int($compressionMethod)) {
                ++$summary['unsupportedCompressionMethodCount'];
            }

            foreach ($itemDiagnostics as $diagnostic) {
                $code = (string) $diagnostic;
                if ($code === '') {
                    continue;
                }

                $diagnostics[] = self::withoutEmpty([
                    'code' => $code,
                    'fullPath' => $item['fullPath'] ?? null,
                    'part' => $item['part'] ?? null,
                    'mediaType' => $mediaType,
                    'exists' => $exists,
                    'isDirectory' => $isDirectory,
                    'canExposeBytes' => ($item['canExposeBytes'] ?? false) === true,
                ]);
            }

            if ($mediaType === '') {
                $emptyMediaTypeParts[] = $part;
                if ($isDirectory) {
                    $emptyMediaTypeDirectoryParts[] = $part;
                } else {
                    $emptyMediaTypeNonDirectoryItems[] = self::withoutEmpty([
                        'fullPath' => $item['fullPath'] ?? null,
                        'part' => $item['part'] ?? null,
                        'exists' => $exists,
                        'storedByteLength' => $storedByteLength,
                        'compressedByteLength' => $compressedByteLength,
                        'compressionMethod' => $compressionMethod,
                        'compressionMethodName' => $item['compressionMethodName'] ?? null,
                        'canExposeBytes' => ($item['canExposeBytes'] ?? false) === true,
                        'byteExposurePolicy' => $item['byteExposurePolicy'] ?? null,
                        'diagnostics' => $itemDiagnostics,
                    ]);
                }
                continue;
            }

            $groupMediaType = $mediaTypeBase === '' ? $mediaType : $mediaTypeBase;
            if (!isset($groups[$groupMediaType])) {
                $groups[$groupMediaType] = [
                    'mediaType' => $groupMediaType,
                    'count' => 0,
                    'parts' => [],
                    'rawMediaTypes' => [],
                    'rawMediaTypeCount' => 0,
                    'parameterizedItemCount' => 0,
                    'mediaTypeParameterNames' => [],
                    'mediaTypeParameterValueCount' => 0,
                    'mediaTypeParameterValuesByName' => [],
                    'mediaTypeParameterValueCounts' => [],
                    'mediaTypeParameterValueSummaries' => [],
                    'existsCount' => 0,
                    'missingCount' => 0,
                    'directoryCount' => 0,
                    'encryptedCount' => 0,
                    'versionedItemCount' => 0,
                    'manifestVersions' => [],
                    'preferredViewModeCount' => 0,
                    'preferredViewModes' => [],
                    'declaredSizeMismatchCount' => 0,
                    'invalidDeclaredSizeCount' => 0,
                    'storedByteLength' => 0,
                    'compressedByteLength' => 0,
                    'exposableByteLength' => 0,
                    'declaredSize' => 0,
                    'storedCompressionMethodCount' => 0,
                    'deflatedCompressionMethodCount' => 0,
                    'unsupportedCompressionMethodCount' => 0,
                ];
                $groupParameterValueRecords[$groupMediaType] = [];
                $groupOrder[] = $groupMediaType;
            }

            ++$summary['typedItemCount'];
            ++$groups[$groupMediaType]['count'];
            $groups[$groupMediaType]['parts'][] = $part;
            if (!in_array($mediaType, $groups[$groupMediaType]['rawMediaTypes'], true)) {
                $groups[$groupMediaType]['rawMediaTypes'][] = $mediaType;
            }
            if (($item['mediaTypeHasParameters'] ?? $mediaTypeReport['mediaTypeHasParameters']) === true) {
                ++$summary['parameterizedItemCount'];
                ++$groups[$groupMediaType]['parameterizedItemCount'];
            }
            foreach ($mediaTypeParameters as $parameter) {
                if (!is_array($parameter)) {
                    continue;
                }
                $name = (string) ($parameter['name'] ?? '');
                if ($name === '') {
                    continue;
                }
                if (!in_array($name, $summary['mediaTypeParameterNames'], true)) {
                    $summary['mediaTypeParameterNames'][] = $name;
                }
                if (!in_array($name, $groups[$groupMediaType]['mediaTypeParameterNames'], true)) {
                    $groups[$groupMediaType]['mediaTypeParameterNames'][] = $name;
                }
                $value = (string) ($parameter['value'] ?? '');
                self::recordMediaTypeParameterValue($parameterValueRecords, $name, $value, $part, $mediaType);
                self::recordMediaTypeParameterValue($groupParameterValueRecords[$groupMediaType], $name, $value, $part, $mediaType);
            }
            if ($exists) {
                ++$groups[$groupMediaType]['existsCount'];
            } else {
                ++$groups[$groupMediaType]['missingCount'];
            }
            if ($isDirectory) {
                ++$groups[$groupMediaType]['directoryCount'];
            }
            if ($encrypted) {
                ++$groups[$groupMediaType]['encryptedCount'];
            }
            if ($manifestVersion !== '') {
                ++$groups[$groupMediaType]['versionedItemCount'];
                if (!in_array($manifestVersion, $groups[$groupMediaType]['manifestVersions'], true)) {
                    $groups[$groupMediaType]['manifestVersions'][] = $manifestVersion;
                }
            }
            if ($preferredViewMode !== '') {
                ++$groups[$groupMediaType]['preferredViewModeCount'];
                if (!in_array($preferredViewMode, $groups[$groupMediaType]['preferredViewModes'], true)) {
                    $groups[$groupMediaType]['preferredViewModes'][] = $preferredViewMode;
                }
            }
            if ($declaredSizeMismatch) {
                ++$groups[$groupMediaType]['declaredSizeMismatchCount'];
            }
            if ($declaredSizeInvalid) {
                ++$groups[$groupMediaType]['invalidDeclaredSizeCount'];
            }
            if (is_int($storedByteLength)) {
                $groups[$groupMediaType]['storedByteLength'] += $storedByteLength;
            }
            if (is_int($byteLength) && ($item['canExposeBytes'] ?? false) === true) {
                $groups[$groupMediaType]['exposableByteLength'] += $byteLength;
            }
            if (is_int($compressedByteLength)) {
                $groups[$groupMediaType]['compressedByteLength'] += $compressedByteLength;
            }
            if (is_int($declaredSize)) {
                $groups[$groupMediaType]['declaredSize'] += $declaredSize;
            }
            if ($compressionMethod === 0) {
                ++$groups[$groupMediaType]['storedCompressionMethodCount'];
            } elseif ($compressionMethod === 8) {
                ++$groups[$groupMediaType]['deflatedCompressionMethodCount'];
            } elseif (is_int($compressionMethod)) {
                ++$groups[$groupMediaType]['unsupportedCompressionMethodCount'];
            }
        }

        $items = [];
        sort($summary['mediaTypeParameterNames'], SORT_STRING);
        $parameterValueRollup = self::mediaTypeParameterValueRollup($parameterValueRecords);
        $summary['mediaTypeParameterValueCount'] = $parameterValueRollup['valueCount'];
        $summary['mediaTypeParameterValuesByName'] = $parameterValueRollup['valuesByName'];
        $summary['mediaTypeParameterValueCounts'] = $parameterValueRollup['valueCounts'];
        $summary['mediaTypeParameterValueSummaries'] = $parameterValueRollup['summaries'];
        foreach ($groupOrder as $mediaType) {
            sort($groups[$mediaType]['mediaTypeParameterNames'], SORT_STRING);
            $groupParameterValueRollup = self::mediaTypeParameterValueRollup(
                $groupParameterValueRecords[$mediaType] ?? []
            );
            $groups[$mediaType]['mediaTypeParameterValueCount'] = $groupParameterValueRollup['valueCount'];
            $groups[$mediaType]['mediaTypeParameterValuesByName'] = $groupParameterValueRollup['valuesByName'];
            $groups[$mediaType]['mediaTypeParameterValueCounts'] = $groupParameterValueRollup['valueCounts'];
            $groups[$mediaType]['mediaTypeParameterValueSummaries'] = $groupParameterValueRollup['summaries'];
            $groups[$mediaType]['rawMediaTypeCount'] = count($groups[$mediaType]['rawMediaTypes']);
            $items[] = $groups[$mediaType];
        }

        $summary['mediaTypeCount'] = count($items);
        $summary['emptyMediaTypeCount'] = count($emptyMediaTypeParts);
        $summary['emptyMediaTypeParts'] = $emptyMediaTypeParts;
        $summary['emptyMediaTypeDirectoryCount'] = count($emptyMediaTypeDirectoryParts);
        $summary['emptyMediaTypeDirectoryParts'] = $emptyMediaTypeDirectoryParts;
        $summary['emptyMediaTypeNonDirectoryCount'] = count($emptyMediaTypeNonDirectoryItems);
        $summary['emptyMediaTypeNonDirectoryItems'] = $emptyMediaTypeNonDirectoryItems;
        $summary['invalidDeclaredSizeItems'] = $invalidDeclaredSizeItems;
        $summary['diagnosticCount'] = count($diagnostics);
        $summary['diagnosticCodeCounts'] = $this->diagnosticCodeCounts($diagnostics);
        $summary['diagnostics'] = $diagnostics;
        $summary['items'] = $items;

        return $summary;
    }

    /**
     * @param array<string, array<string, array<string, mixed>>> $records
     */
    private static function recordMediaTypeParameterValue(
        array &$records,
        string $name,
        string $value,
        string $part,
        string $mediaType
    ): void {
        if ($name === '') {
            return;
        }

        $records[$name] ??= [];
        $records[$name][$value] ??= [
            'name' => $name,
            'value' => $value,
            'occurrenceCount' => 0,
            'parts' => [],
            'mediaTypes' => [],
        ];
        ++$records[$name][$value]['occurrenceCount'];
        if (!in_array($part, $records[$name][$value]['parts'], true)) {
            $records[$name][$value]['parts'][] = $part;
        }
        if (!in_array($mediaType, $records[$name][$value]['mediaTypes'], true)) {
            $records[$name][$value]['mediaTypes'][] = $mediaType;
        }
    }

    /**
     * @param array<string, array<string, array<string, mixed>>> $records
     * @return array{valueCount:int, valuesByName:array<string, list<string>>, valueCounts:array<string, array<string, int>>, summaries:list<array{name:string, value:string, occurrenceCount:int, partCount:int, parts:list<string>, mediaTypeCount:int, mediaTypes:list<string>}>}
     */
    private static function mediaTypeParameterValueRollup(array $records): array
    {
        $valuesByName = [];
        $valueCounts = [];
        $summaries = [];

        ksort($records, SORT_STRING);
        foreach ($records as $name => $values) {
            ksort($values, SORT_STRING);
            foreach ($values as $value => $record) {
                $parts = is_array($record['parts'] ?? null) ? $record['parts'] : [];
                $mediaTypes = is_array($record['mediaTypes'] ?? null) ? $record['mediaTypes'] : [];
                sort($parts, SORT_STRING);
                sort($mediaTypes, SORT_STRING);

                $valuesByName[$name] ??= [];
                if (!in_array((string) $value, $valuesByName[$name], true)) {
                    $valuesByName[$name][] = (string) $value;
                }
                $valueCounts[$name] ??= [];
                $valueCounts[$name][(string) $value] = (int) ($record['occurrenceCount'] ?? 0);
                $summaries[] = [
                    'name' => $name,
                    'value' => (string) $value,
                    'occurrenceCount' => (int) ($record['occurrenceCount'] ?? 0),
                    'partCount' => count($parts),
                    'parts' => array_values($parts),
                    'mediaTypeCount' => count($mediaTypes),
                    'mediaTypes' => array_values($mediaTypes),
                ];
            }
        }

        return [
            'valueCount' => count($summaries),
            'valuesByName' => $valuesByName,
            'valueCounts' => $valueCounts,
            'summaries' => $summaries,
        ];
    }

    /**
     * @param array<string, mixed> $item
     */
    private static function manifestItemPartLabel(array $item): string
    {
        $part = $item['part'] ?? null;
        if (is_string($part) && $part !== '') {
            return $part;
        }

        $fullPath = $item['fullPath'] ?? null;
        if (is_string($fullPath) && $fullPath !== '') {
            return $fullPath;
        }

        return '/';
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @param array<string, array<string, mixed>> $objectPackageRootParts
     * @return array{manifestDeclaredSizeRoleCount:int, manifestDeclaredSizeRoleCounts:array<string, int>, manifestDeclaredSizeRoleByteLengths:array<string, int>, manifestDeclaredSizeRoleMismatchCounts:array<string, int>, manifestDeclaredSizeRoleExistingCounts:array<string, int>, manifestDeclaredSizeRoleMissingCounts:array<string, int>, manifestDeclaredSizeRoleSummaries:list<array{role:string, declaredSizeItemCount:int, declaredSize:int, declaredSizeMismatchCount:int, existingCount:int, missingCount:int, parts:list<string>}>}
     */
    private function manifestDeclaredSizeRoleSummary(array $manifest, array $objectPackageRootParts): array
    {
        $roleCounts = [];
        $roleByteLengths = [];
        $roleMismatchCounts = [];
        $roleExistingCounts = [];
        $roleMissingCounts = [];
        $partsByRole = [];

        foreach ($manifest as $item) {
            $declaredSize = $item['declaredSize'] ?? null;
            if (!is_int($declaredSize)) {
                continue;
            }

            $part = self::manifestItemPartLabel($item);
            foreach ($this->missingManifestDeclaredRoles($item, $objectPackageRootParts) as $role) {
                $roleCounts[$role] = ($roleCounts[$role] ?? 0) + 1;
                $roleByteLengths[$role] = ($roleByteLengths[$role] ?? 0) + $declaredSize;
                if (($item['declaredSizeMismatch'] ?? false) === true) {
                    $roleMismatchCounts[$role] = ($roleMismatchCounts[$role] ?? 0) + 1;
                }
                if (($item['exists'] ?? false) === true) {
                    $roleExistingCounts[$role] = ($roleExistingCounts[$role] ?? 0) + 1;
                } else {
                    $roleMissingCounts[$role] = ($roleMissingCounts[$role] ?? 0) + 1;
                }
                $partsByRole[$role] ??= [];
                if (!in_array($part, $partsByRole[$role], true)) {
                    $partsByRole[$role][] = $part;
                }
            }
        }

        ksort($roleCounts, SORT_STRING);
        ksort($roleByteLengths, SORT_STRING);
        ksort($roleMismatchCounts, SORT_STRING);
        ksort($roleExistingCounts, SORT_STRING);
        ksort($roleMissingCounts, SORT_STRING);
        ksort($partsByRole, SORT_STRING);

        $summaries = [];
        foreach (array_keys($roleCounts) as $role) {
            $summaries[] = [
                'role' => $role,
                'declaredSizeItemCount' => $roleCounts[$role],
                'declaredSize' => $roleByteLengths[$role] ?? 0,
                'declaredSizeMismatchCount' => $roleMismatchCounts[$role] ?? 0,
                'existingCount' => $roleExistingCounts[$role] ?? 0,
                'missingCount' => $roleMissingCounts[$role] ?? 0,
                'parts' => $partsByRole[$role] ?? [],
            ];
        }

        return [
            'manifestDeclaredSizeRoleCount' => count($roleCounts),
            'manifestDeclaredSizeRoleCounts' => $roleCounts,
            'manifestDeclaredSizeRoleByteLengths' => $roleByteLengths,
            'manifestDeclaredSizeRoleMismatchCounts' => $roleMismatchCounts,
            'manifestDeclaredSizeRoleExistingCounts' => $roleExistingCounts,
            'manifestDeclaredSizeRoleMissingCounts' => $roleMissingCounts,
            'manifestDeclaredSizeRoleSummaries' => $summaries,
        ];
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @return list<array<string, mixed>>
     */
    private function manifestDeclaredSizeMismatches(array $manifest): array
    {
        $mismatches = [];
        foreach ($manifest as $item) {
            if (($item['declaredSizeMismatch'] ?? false) !== true) {
                continue;
            }

            $mismatches[] = self::withoutEmpty([
                'fullPath' => $item['fullPath'] ?? null,
                'part' => $item['part'] ?? null,
                'mediaType' => $item['mediaType'] ?? null,
                'declaredSize' => $item['declaredSize'] ?? null,
                'byteLength' => $item['byteLength'] ?? null,
                'storedByteLength' => $item['storedByteLength'] ?? null,
                'crc32' => $item['crc32'] ?? null,
                'storedCrc32' => $item['storedCrc32'] ?? null,
            ]);
        }

        return $mismatches;
    }

    /**
     * @param list<array<string, mixed>> $manifest
     * @return list<array<string, mixed>>
     */
    private function manifestUndeclaredPackageEntries(ZipPackage $package, array $manifest): array
    {
        $declaredParts = [
            'mimetype' => true,
            'META-INF/manifest.xml' => true,
        ];
        foreach ($manifest as $item) {
            $part = $item['part'] ?? null;
            if (is_string($part) && $part !== '') {
                $declaredParts[$part] = true;
            }
        }

        $entries = [];
        $objectPackageRootParts = $this->objectPackageRootParts($manifest);
        foreach ($package->entries() as $entry) {
            if ($entry->isDirectory() || isset($declaredParts[$entry->name])) {
                continue;
            }

            $embeddedObjectPackage = $this->embeddedObjectPackageMembership($entry->name, $objectPackageRootParts);
            $byteExposurePolicy = $this->undeclaredPackageEntryByteExposurePolicy($entry->name, $embeddedObjectPackage);
            $entries[] = [
                'part' => $entry->name,
                'diagnostic' => 'odf-manifest-undeclared-package-entry',
                'byteLength' => $entry->uncompressedSize,
                'compressedByteLength' => $entry->compressedSize,
                'compressionMethod' => $entry->compressionMethod,
                'compressionMethodName' => self::compressionMethodName($entry->compressionMethod),
                'crc32' => $entry->crc32Hex(),
                'thumbnailPackagePart' => $this->isThumbnailPackagePartName($entry->name),
                'scriptPackagePart' => $this->isScriptPackagePartName($entry->name),
                'signaturePackagePart' => $this->isSignaturePartName($entry->name),
                'configurationPackagePart' => self::isConfigurationPackagePartName($entry->name),
                'fontPackagePart' => $this->isFontPackagePartName($entry->name),
                'rdfMetadataPart' => $this->isRdfPartName($entry->name),
                'objectReplacementPackagePart' => $this->isObjectReplacementPackagePartName($entry->name),
                'layoutCachePackagePart' => $this->isLayoutCachePackagePartName($entry->name),
                'metaInfSidecarPackagePart' => $this->isMetaInfSidecarPackagePartName($entry->name),
                'databasePackagePart' => $this->isDatabasePackagePartName($entry->name),
                'canExposeBytes' => false,
                'byteExposurePolicy' => $byteExposurePolicy,
                'diagnostics' => ['odf-manifest-undeclared-package-entry'],
            ];
        }

        return $entries;
    }

    /**
     * @param array<string, mixed>|null $embeddedObjectPackage
     */
    private function undeclaredPackageEntryByteExposurePolicy(string $part, ?array $embeddedObjectPackage = null): string
    {
        if (is_array($embeddedObjectPackage)) {
            return 'embedded-object-package-bytes-blocked';
        }
        if ($this->isThumbnailPackagePartName($part)) {
            return 'package-thumbnail-bytes-blocked';
        }
        if ($this->isScriptPackagePartName($part)) {
            return 'script-package-bytes-blocked';
        }
        if ($this->isSignaturePartName($part)) {
            return 'signature-package-bytes-blocked';
        }
        if (self::isConfigurationPackagePartName($part)) {
            return 'configuration-package-bytes-blocked';
        }
        if ($this->isFontPackagePartName($part)) {
            return 'font-package-bytes-blocked';
        }
        if ($this->isRdfPartName($part)) {
            return 'rdf-metadata-bytes-blocked';
        }
        if ($this->isObjectReplacementPackagePartName($part)) {
            return 'object-replacement-package-bytes-blocked';
        }
        if ($this->isLayoutCachePackagePartName($part)) {
            return 'layout-cache-package-bytes-blocked';
        }
        if ($this->isMetaInfSidecarPackagePartName($part)) {
            return 'meta-inf-sidecar-package-bytes-blocked';
        }
        if ($this->isDatabasePackagePartName($part)) {
            return 'database-package-bytes-blocked';
        }

        return 'undeclared-package-entry-no-bytes';
    }

    /**
     * @param list<AstNode> $nodes
     * @return array{blockquoteCount:int, noteCount:int, bookmarkCount:int, bookmarkReferenceCount:int, referenceMarkCount:int, referenceReferenceCount:int, indexMarkCount:int, sequenceCount:int, fieldCount:int, metaSpanCount:int, placeholderCount:int, rubyCount:int, softPageBreakCount:int, citationCount:int, eventListenerCount:int, annotationRangeCount:int, trackedChangeCount:int, mathCount:int, embeddedObjectCount:int, missingEmbeddedObjectCount:int, chartObjectCount:int, chartMetadataCount:int, formControlCount:int, missingFormControlCount:int, formControlOptionCount:int, selectedFormControlOptionCount:int, sectionCount:int, linkedSectionCount:int, protectedSectionCount:int, conditionalSectionCount:int, hiddenSectionCount:int, tableOfContentsCount:int, generatedIndexCount:int, tableCaptionCount:int, preformattedCodeBlockCount:int, continuedListCount:int, listHeaderCount:int, tableTemplateReferenceCount:int, tablePrintRangeCount:int, tableScenarioCount:int, activeTableScenarioCount:int, tableColumnDefinitionCount:int, hiddenTableColumnCount:int, tableRowDefinitionCount:int, hiddenTableRowCount:int, repeatedTableRowCount:int, truncatedTableRowRepeatCount:int}
     */
    private function contentNodeStats(array $nodes): array
    {
        $stats = [
            'blockquoteCount' => 0,
            'noteCount' => 0,
            'bookmarkCount' => 0,
            'bookmarkReferenceCount' => 0,
            'referenceMarkCount' => 0,
            'referenceReferenceCount' => 0,
            'indexMarkCount' => 0,
            'sequenceCount' => 0,
            'fieldCount' => 0,
            'metaSpanCount' => 0,
            'placeholderCount' => 0,
            'rubyCount' => 0,
            'softPageBreakCount' => 0,
            'citationCount' => 0,
            'eventListenerCount' => 0,
            'annotationRangeCount' => 0,
            'trackedChangeCount' => 0,
            'mathCount' => 0,
            'embeddedObjectCount' => 0,
            'missingEmbeddedObjectCount' => 0,
            'chartObjectCount' => 0,
            'chartMetadataCount' => 0,
            'chartTitleCount' => 0,
            'chartAxisCount' => 0,
            'chartLegendCount' => 0,
            'formControlCount' => 0,
            'missingFormControlCount' => 0,
            'formControlOptionCount' => 0,
            'selectedFormControlOptionCount' => 0,
            'sectionCount' => 0,
            'linkedSectionCount' => 0,
            'protectedSectionCount' => 0,
            'conditionalSectionCount' => 0,
            'hiddenSectionCount' => 0,
            'tableOfContentsCount' => 0,
            'generatedIndexCount' => 0,
            'tableCaptionCount' => 0,
            'preformattedCodeBlockCount' => 0,
            'continuedListCount' => 0,
            'listHeaderCount' => 0,
            'imageListStyleCount' => 0,
            'listTextPropertyCount' => 0,
            'tableTemplateReferenceCount' => 0,
            'tablePrintRangeCount' => 0,
            'tableScenarioCount' => 0,
            'activeTableScenarioCount' => 0,
            'tableColumnDefinitionCount' => 0,
            'hiddenTableColumnCount' => 0,
            'tableRowDefinitionCount' => 0,
            'hiddenTableRowCount' => 0,
            'repeatedTableRowCount' => 0,
            'truncatedTableRowRepeatCount' => 0,
            'tableCoveredCellCount' => 0,
            'tableCoveredCellMetadataCount' => 0,
            'tableCellAnnotationCount' => 0,
            'tableCellDetectiveCount' => 0,
            'tableCellDetectiveHighlightCount' => 0,
            'tableCellDetectiveOperationCount' => 0,
            'tableStyledCellCount' => 0,
            'tableDataStyledCellCount' => 0,
            'tableDataStyleDefinitionCellCount' => 0,
            'tableProtectedCellCount' => 0,
            'tablePrintHiddenCellCount' => 0,
            'frameLayerReferenceCount' => 0,
            'frameCaptionCount' => 0,
        ];
        foreach ($nodes as $node) {
            if ($node->type === 'note') {
                $stats['noteCount']++;
            }
            if ($node->type === 'blockquote' && $this->nodeHasClass($node, 'odf-blockquote')) {
                $stats['blockquoteCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-section')) {
                $stats['sectionCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-linked-section')) {
                $stats['linkedSectionCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-protected-section')) {
                $stats['protectedSectionCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-conditional-section')) {
                $stats['conditionalSectionCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-hidden-section')) {
                $stats['hiddenSectionCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-table-of-contents')) {
                $stats['tableOfContentsCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-generated-index')) {
                $stats['generatedIndexCount']++;
            }
            if ($node->type === 'div' && $this->nodeHasClass($node, 'odf-table-caption')) {
                $stats['tableCaptionCount']++;
            }
            if ($node->type === 'figure' && $this->nodeHasClass($node, 'odf-frame-caption')) {
                $stats['frameCaptionCount']++;
            }
            if ($node->type === 'table' && $node->attr('odfCaptionParagraph') === true) {
                $stats['tableCaptionCount']++;
            }
            if ($node->type === 'code_block' && $node->attr('odfPreformatted') === true) {
                $stats['preformattedCodeBlockCount']++;
            }
            if ($node->type === 'table' && (string) $node->attr('templateName', '') !== '') {
                $stats['tableTemplateReferenceCount']++;
            }
            if ($node->type === 'table') {
                $printRanges = $node->attr('odfPrintRanges', []);
                if (is_array($printRanges)) {
                    $stats['tablePrintRangeCount'] += count($printRanges);
                }
            }
            if ($node->type === 'table') {
                $scenarios = $node->attr('odfTableScenarios', []);
                if (is_array($scenarios)) {
                    $stats['tableScenarioCount'] += count($scenarios);
                    $stats['activeTableScenarioCount'] += $this->activeTableScenarioCount($scenarios);
                }
            }
            if ($node->type === 'table') {
                $columns = $node->attr('odfTableColumns', []);
                if (is_array($columns)) {
                    $stats['tableColumnDefinitionCount'] += count($columns);
                    foreach ($columns as $column) {
                        if (is_array($column) && ($column['hidden'] ?? false) === true) {
                            $stats['hiddenTableColumnCount']++;
                        }
                    }
                }
            }
            if ($node->type === 'table_row' && $node->attr('odfTableRowMetadata', []) !== []) {
                $stats['tableRowDefinitionCount']++;
                if ($node->attr('hidden') === true) {
                    $stats['hiddenTableRowCount']++;
                }
                if (is_numeric($node->attr('sourceRepeat', 0)) && (int) $node->attr('sourceRepeat', 0) > 1) {
                    $stats['repeatedTableRowCount']++;
                }
                if ($node->attr('repeatTruncated') === true) {
                    $stats['truncatedTableRowRepeatCount']++;
                }
            }
            $coveredCells = $node->attr('odfCoveredCells', []);
            if (is_array($coveredCells) && $coveredCells !== []) {
                $stats['tableCoveredCellCount'] += count($coveredCells);
                foreach ($coveredCells as $coveredCell) {
                    if (is_array($coveredCell) && $this->coveredTableCellHasReviewMetadata($coveredCell)) {
                        $stats['tableCoveredCellMetadataCount']++;
                    }
                }
            }
            if ($node->type === 'table_cell' && $node->attr('odfCellStyleProperties', []) !== []) {
                $stats['tableStyledCellCount']++;
                $properties = $node->attr('odfCellStyleProperties', []);
                if (is_array($properties) && (string) ($properties['cellProtect'] ?? '') !== '') {
                    $stats['tableProtectedCellCount']++;
                }
                if (is_array($properties) && ($properties['printContent'] ?? null) === false) {
                    $stats['tablePrintHiddenCellCount']++;
                }
            }
            if ($node->type === 'table_cell' && (string) $node->attr('odfCellDataStyleName', '') !== '') {
                $stats['tableDataStyledCellCount']++;
                if (is_array($node->attr('odfCellDataStyle', null))) {
                    $stats['tableDataStyleDefinitionCellCount']++;
                }
            }
            $cellAnnotations = $node->attr('odfCellAnnotations', []);
            if ($node->type === 'table_cell' && is_array($cellAnnotations)) {
                $stats['tableCellAnnotationCount'] += count($cellAnnotations);
            }
            $cellDetective = $node->attr('odfCellDetective', []);
            if ($node->type === 'table_cell' && is_array($cellDetective) && $cellDetective !== []) {
                $stats['tableCellDetectiveCount']++;
                $highlightedRanges = $cellDetective['highlightedRanges'] ?? [];
                if (is_array($highlightedRanges)) {
                    $stats['tableCellDetectiveHighlightCount'] += count($highlightedRanges);
                }
                $operations = $cellDetective['operations'] ?? [];
                if (is_array($operations)) {
                    $stats['tableCellDetectiveOperationCount'] += count($operations);
                }
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-bookmark')) {
                $stats['bookmarkCount']++;
            }
            if ($node->type === 'link' && $this->nodeHasClass($node, 'odf-bookmark-ref')) {
                $stats['bookmarkReferenceCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-reference-mark')) {
                $stats['referenceMarkCount']++;
            }
            if ($node->type === 'link' && $this->nodeHasClass($node, 'odf-reference-ref')) {
                $stats['referenceReferenceCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-index-mark')) {
                $stats['indexMarkCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-sequence')) {
                $stats['sequenceCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-field')) {
                $stats['fieldCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-meta')) {
                $stats['metaSpanCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-placeholder')) {
                $stats['placeholderCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-ruby')) {
                $stats['rubyCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-soft-page-break')) {
                $stats['softPageBreakCount']++;
            }
            if ($node->type === 'citation') {
                $stats['citationCount']++;
            }
            if ($node->type === 'link') {
                $linkMetadata = $node->attr('odfLinkMetadata', []);
                $eventListeners = is_array($linkMetadata) ? ($linkMetadata['eventListeners'] ?? []) : [];
                if (is_array($eventListeners)) {
                    $stats['eventListenerCount'] += count($eventListeners);
                }
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-annotation-range')) {
                $stats['annotationRangeCount']++;
            }
            if ($node->type === 'span' && $this->nodeHasClass($node, 'odf-change')) {
                $stats['trackedChangeCount']++;
            }
            if ($node->type === 'math') {
                $stats['mathCount']++;
            }
            if (($node->type === 'span' || $node->type === 'div') && $this->nodeHasClass($node, 'odf-embedded-object')) {
                $stats['embeddedObjectCount']++;
                if ($node->attr('exists') !== true) {
                    $stats['missingEmbeddedObjectCount']++;
                }
                if ($node->attr('objectType') === 'chart') {
                    $stats['chartObjectCount']++;
                    $chartMetadata = $node->attr('chartMetadata');
                    if (is_array($chartMetadata)) {
                        $stats['chartMetadataCount']++;
                        $title = $chartMetadata['title'] ?? null;
                        if (is_array($title) && is_scalar($title['text'] ?? null) && (string) $title['text'] !== '') {
                            $stats['chartTitleCount']++;
                        }
                        $axes = $chartMetadata['axes'] ?? [];
                        if (is_array($axes)) {
                            $stats['chartAxisCount'] += count($axes);
                        }
                        $legend = $chartMetadata['legend'] ?? null;
                        if (is_array($legend) && $legend !== []) {
                            $stats['chartLegendCount']++;
                        }
                    }
                }
            }
            if (($node->type === 'span' || $node->type === 'div') && $this->nodeHasClass($node, 'odf-form-control')) {
                $stats['formControlCount']++;
                if ($node->attr('exists') !== true) {
                    $stats['missingFormControlCount']++;
                }
                $formControl = $node->attr('formControl');
                if (is_array($formControl)) {
                    $options = $formControl['options'] ?? [];
                    if (is_array($options)) {
                        $stats['formControlOptionCount'] += count($options);
                        foreach ($options as $option) {
                            if (is_array($option) && ($option['selected'] ?? false) === true) {
                                $stats['selectedFormControlOptionCount']++;
                            }
                        }
                    }
                }
            }
            $frameMetadata = $node->attr('odfFrameMetadata');
            if (is_array($frameMetadata) && (string) ($frameMetadata['layer'] ?? '') !== '') {
                $stats['frameLayerReferenceCount']++;
            }
            if (($node->type === 'ordered_list' || $node->type === 'bullet_list') && $node->attr('continued') === true) {
                $stats['continuedListCount']++;
            }
            if ($node->type === 'list_item' && $node->attr('listHeader') === true) {
                $stats['listHeaderCount']++;
            }
            if (($node->type === 'ordered_list' || $node->type === 'bullet_list') && $node->attr('listImageStyle') === true) {
                $stats['imageListStyleCount']++;
            }
            $listTextProperties = $node->attr('listTextProperties', []);
            if (($node->type === 'ordered_list' || $node->type === 'bullet_list')
                && is_array($listTextProperties)
                && $listTextProperties !== []
            ) {
                $stats['listTextPropertyCount']++;
            }

            $childStats = $this->contentNodeStats($node->children);
            foreach ($childStats as $name => $count) {
                $stats[$name] += $count;
            }
        }

        return $stats;
    }

    private function nodeHasClass(AstNode $node, string $class): bool
    {
        $classes = $node->attr('classes', []);
        if (!is_array($classes)) {
            return false;
        }

        return in_array($class, array_map(static fn (mixed $value): string => (string) $value, $classes), true);
    }

    private function manifestPackagePart(string $path, bool $allowLeadingCurrentDirectory = true): string
    {
        $rawPath = preg_replace('/[#?].*$/', '', $path) ?? $path;
        if ($rawPath === '') {
            throw new \RuntimeException('ODT package part path must not be empty');
        }
        if (preg_match('/%(?![0-9A-Fa-f]{2})/', $rawPath) === 1) {
            throw new \InvalidArgumentException('Malformed percent escape in ODT package part path: ' . $path);
        }
        if ((!$allowLeadingCurrentDirectory && str_starts_with($rawPath, '/')) || str_contains($rawPath, '\\') || self::hasAsciiControlByte($rawPath)) {
            throw new \InvalidArgumentException('ODT package part path is not a safe package-relative path: ' . $path);
        }

        $decodedPath = rawurldecode($rawPath);
        if ($allowLeadingCurrentDirectory) {
            $decodedPath = ltrim($decodedPath, '/');
            while (str_starts_with($decodedPath, './')) {
                $decodedPath = substr($decodedPath, 2);
            }
        }

        if (
            $decodedPath === ''
            || (!$allowLeadingCurrentDirectory && str_starts_with($decodedPath, '/'))
            || str_contains($decodedPath, '\\')
            || self::hasAsciiControlByte($decodedPath)
            || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $decodedPath) === 1
        ) {
            throw new \InvalidArgumentException('ODT package part path is not a safe package-relative path: ' . $path);
        }

        $segments = explode('/', $decodedPath);
        foreach ($segments as $index => $segment) {
            $isTrailingDirectorySegment = $index === count($segments) - 1 && $segment === '';
            if ($isTrailingDirectorySegment) {
                continue;
            }

            if ($segment === '' || $segment === '.' || $segment === '..') {
                throw new \InvalidArgumentException('ODT package part path is not a safe package-relative path: ' . $path);
            }
        }

        return $decodedPath;
    }

    private static function hasAsciiControlByte(string $value): bool
    {
        return preg_match('/[\x00-\x1F\x7F]/', $value) === 1;
    }

    /**
     * @return array{part:string,partReference:string,partSuffix:string|null,partQuery:string|null,partFragment:string|null}
     */
    private function manifestPackageReference(string $path, bool $allowLeadingCurrentDirectory = true): array
    {
        $partReference = $path;
        $partSuffix = null;
        $partQuery = null;
        $partFragment = null;
        $suffixOffset = strcspn($path, '?#');
        if ($suffixOffset < strlen($path)) {
            $partReference = substr($path, 0, $suffixOffset);
            $partSuffix = substr($path, $suffixOffset);
            if (str_starts_with($partSuffix, '?')) {
                $queryAndFragment = substr($partSuffix, 1);
                $fragmentOffset = strpos($queryAndFragment, '#');
                if ($fragmentOffset === false) {
                    $partQuery = $queryAndFragment;
                } else {
                    $partQuery = substr($queryAndFragment, 0, $fragmentOffset);
                    $partFragment = substr($queryAndFragment, $fragmentOffset + 1);
                }
            } elseif (str_starts_with($partSuffix, '#')) {
                $partFragment = substr($partSuffix, 1);
            }
        }

        return [
            'part' => $this->manifestPackagePart($partReference, $allowLeadingCurrentDirectory),
            'partReference' => $partReference,
            'partSuffix' => $partSuffix,
            'partQuery' => $partQuery,
            'partFragment' => $partFragment,
        ];
    }

    /**
     * @return array{part:null,partReference:null,partSuffix:null,partQuery:null,partFragment:null}
     */
    private static function rootManifestPackageReference(): array
    {
        return [
            'part' => null,
            'partReference' => null,
            'partSuffix' => null,
            'partQuery' => null,
            'partFragment' => null,
        ];
    }

    /**
     * @return list<AstNode>
     */
    private function coalesceTextNodes(array $nodes): array
    {
        $coalesced = [];
        foreach ($nodes as $node) {
            if ($node->type === 'text' && $coalesced !== []) {
                $last = $coalesced[count($coalesced) - 1];
                if ($last->type === 'text') {
                    $attrs = $last->attrs;
                    $attrs['text'] = (string) ($attrs['text'] ?? '') . (string) $node->attr('text', '');
                    $coalesced[count($coalesced) - 1] = new AstNode('text', $attrs, $last->children);
                    continue;
                }
            }

            $coalesced[] = $node;
        }

        return $coalesced;
    }

    /**
     * @param list<AstNode> $inlines
     * @return array{inlines:list<AstNode>, anchor:?array{id:string, bookmarkName:string}}
     */
    private function extractHeadingBookmarkAnchor(array $inlines): array
    {
        $filtered = [];
        $anchor = null;
        foreach ($inlines as $node) {
            if ($anchor === null && $this->nodeHasClass($node, 'odf-bookmark')) {
                $id = (string) $node->attr('id', '');
                $attributes = $node->attr('attributes', []);
                $bookmarkName = is_array($attributes) ? (string) ($attributes['data-odf-bookmark-name'] ?? '') : '';
                if ($id !== '' && $bookmarkName !== '') {
                    $anchor = [
                        'id' => $id,
                        'bookmarkName' => $bookmarkName,
                    ];
                    continue;
                }
            }

            $filtered[] = $node;
        }

        return [
            'inlines' => $filtered,
            'anchor' => $anchor,
        ];
    }

    /**
     * @param array<string, mixed> $attrs
     * @param array{id:string, bookmarkName:string} $anchor
     */
    private function addHeadingBookmarkAnchorAttrs(array &$attrs, array $anchor): void
    {
        $attrs['odfHeadingAnchor'] = [
            'source' => 'bookmark',
            'bookmarkName' => $anchor['bookmarkName'],
            'id' => $attrs['id'],
        ];
        $attrs['attributes']['data-odf-heading-anchor-source'] = 'bookmark';
        $attrs['attributes']['data-odf-heading-bookmark-name'] = $anchor['bookmarkName'];
        $attrs['attributes']['data-odf-heading-anchor-id'] = $attrs['id'];
    }

    /**
     * @return ?array{sourceId:string, attributeName:string}
     */
    private function headingAttributeAnchor(\DOMElement $heading): ?array
    {
        $textId = self::attr($heading, self::TEXT_NS, 'id');
        if ($textId !== '') {
            return [
                'sourceId' => $textId,
                'attributeName' => 'text:id',
            ];
        }

        $xmlId = self::attr($heading, self::XML_NS, 'id');
        if ($xmlId !== '') {
            return [
                'sourceId' => $xmlId,
                'attributeName' => 'xml:id',
            ];
        }

        return null;
    }

    /**
     * @param array<string, mixed> $attrs
     * @param array{sourceId:string, attributeName:string} $anchor
     */
    private function addHeadingAttributeAnchorAttrs(array &$attrs, array $anchor): void
    {
        $attrs['odfHeadingAnchor'] = [
            'source' => 'attribute',
            'attributeName' => $anchor['attributeName'],
            'sourceId' => $anchor['sourceId'],
            'id' => $attrs['id'],
        ];
        $attrs['attributes']['data-odf-heading-anchor-source'] = 'attribute';
        $attrs['attributes']['data-odf-heading-source-attribute'] = $anchor['attributeName'];
        $attrs['attributes']['data-odf-heading-source-id'] = $anchor['sourceId'];
        $attrs['attributes']['data-odf-heading-anchor-id'] = $attrs['id'];
    }

    /**
     * @param list<AstNode> $nodes
     */
    private function plainInlineText(array $nodes): string
    {
        $text = '';
        foreach ($nodes as $node) {
            if ($node->type === 'text') {
                $text .= (string) $node->attr('text', '');
                continue;
            }
            if ($node->type === 'code') {
                $text .= (string) $node->attr('text', '');
                continue;
            }
            if ($node->type === 'linebreak') {
                $text .= "\n";
                continue;
            }
            if ($node->type === 'image') {
                $text .= (string) $node->attr('alt', '');
                continue;
            }
            if ($node->type === 'math') {
                $text .= (string) $node->attr('text', '');
                continue;
            }
            if ($node->type === 'note') {
                continue;
            }
            $text .= $this->plainInlineText($node->children);
        }

        return $text;
    }

    /**
     * @param list<AstNode> $blocks
     */
    private function plainBlockText(array $blocks): string
    {
        $parts = [];
        foreach ($blocks as $block) {
            if ($block->children !== []) {
                $parts[] = $this->plainInlineText($block->children);
            } else {
                $parts[] = (string) $block->attr('text', '');
            }
        }

        return trim(implode(' ', array_filter($parts, static fn (string $part): bool => $part !== '')));
    }

    private function lengthToPoints(string $length): ?float
    {
        if ($length === '' || preg_match('/^([0-9]+(?:\.[0-9]+)?)(cm|mm|in|pt)$/', $length, $matches) !== 1) {
            return null;
        }

        $value = (float) $matches[1];

        return match ($matches[2]) {
            'cm' => $value * 28.3464567,
            'mm' => $value * 2.83464567,
            'in' => $value * 72.0,
            default => $value,
        };
    }

    private function isElement(\DOMElement $element, string $namespace, string $localName): bool
    {
        return $element->namespaceURI === $namespace && $element->localName === $localName;
    }

    private static function isOfficeDocumentPartRoot(\DOMElement $root, string $specificLocalName): bool
    {
        return $root->namespaceURI === self::OFFICE_NS
            && ($root->localName === $specificLocalName || $root->localName === 'document');
    }

    private static function loadXml(string $xml, string $label): \DOMDocument
    {
        $dom = new \DOMDocument();
        $previous = libxml_use_internal_errors(true);
        try {
            $loaded = $dom->loadXML($xml, LIBXML_NONET);
            if (!$loaded) {
                $errors = libxml_get_errors();
                $message = $errors === [] ? 'unknown XML parse error' : trim($errors[0]->message);
                throw new \InvalidArgumentException("Unable to parse {$label}: {$message}");
            }
        } finally {
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
        }

        return $dom;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function childElements(\DOMElement $element, ?string $localName = null, ?string $namespace = null): array
    {
        $elements = [];
        foreach ($element->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }
            if ($localName !== null && $child->localName !== $localName) {
                continue;
            }
            if ($namespace !== null && $child->namespaceURI !== $namespace) {
                continue;
            }
            $elements[] = $child;
        }

        return $elements;
    }

    private static function firstChildElement(\DOMElement $element, ?string $localName = null, ?string $namespace = null): ?\DOMElement
    {
        foreach (self::childElements($element, $localName, $namespace) as $child) {
            return $child;
        }

        return null;
    }

    private static function signatureQualifiedElementName(\DOMElement $element): string
    {
        $prefix = (string) $element->prefix;

        return $prefix === '' ? $element->localName : $prefix . ':' . $element->localName;
    }

    /**
     * @param array<string, int> $target
     * @param mixed $source
     */
    private static function mergeIntCounts(array &$target, mixed $source): void
    {
        if (!is_array($source)) {
            return;
        }

        foreach ($source as $key => $value) {
            if (!is_string($key) || $key === '') {
                continue;
            }
            $target[$key] = ($target[$key] ?? 0) + (int) $value;
        }
    }

    private static function attr(\DOMElement $element, string $namespace, string $name): string
    {
        return trim($element->getAttributeNS($namespace, $name));
    }

    private static function domAttribute(\DOMElement $element, string $name): string
    {
        return trim($element->getAttribute($name));
    }

    private static function intAttr(\DOMElement $element, string $namespace, string $name, int $default): int
    {
        $value = self::attr($element, $namespace, $name);

        return ctype_digit($value) ? (int) $value : $default;
    }

    private static function nullableInt(string $value): ?int
    {
        return ctype_digit($value) ? (int) $value : null;
    }

    /**
     * @return array{raw:string|null,value:int|null,valid:bool,invalid:bool}
     */
    private static function manifestDeclaredSize(string $value): array
    {
        $raw = trim($value);
        if ($raw === '') {
            return [
                'raw' => null,
                'value' => null,
                'valid' => false,
                'invalid' => false,
            ];
        }

        if (!ctype_digit($raw)) {
            return [
                'raw' => $raw,
                'value' => null,
                'valid' => false,
                'invalid' => true,
            ];
        }

        $normalized = ltrim($raw, '0');
        $normalized = $normalized === '' ? '0' : $normalized;
        $max = (string) PHP_INT_MAX;
        if (strlen($normalized) > strlen($max) || (strlen($normalized) === strlen($max) && strcmp($normalized, $max) > 0)) {
            return [
                'raw' => $raw,
                'value' => null,
                'valid' => false,
                'invalid' => true,
            ];
        }

        return [
            'raw' => $raw,
            'value' => (int) $normalized,
            'valid' => true,
            'invalid' => false,
        ];
    }

    private static function nullableBool(string $value): ?bool
    {
        $value = strtolower(trim($value));
        if ($value === '') {
            return null;
        }

        return in_array($value, ['true', '1', 'yes', 'checked'], true);
    }

    private static function typedOdfAttributeValue(string $value): mixed
    {
        $normalized = strtolower(trim($value));
        if ($normalized === 'true' || $normalized === 'false') {
            return $normalized === 'true';
        }

        if (preg_match('/^-?\d+$/', $value) === 1) {
            return (int) $value;
        }

        return $value;
    }

    private static function nullable(string $value): ?string
    {
        return $value === '' ? null : $value;
    }

    /**
     * @param array<string, mixed> $values
     * @return array<string, mixed>
     */
    private static function withoutEmpty(array $values): array
    {
        return array_filter(
            $values,
            static fn (mixed $value): bool => $value !== null && $value !== '' && $value !== []
        );
    }

    private static function canonicalIdentityValue(mixed $value): mixed
    {
        if (!is_array($value)) {
            return $value;
        }

        if (array_is_list($value)) {
            return array_map(static fn (mixed $item): mixed => self::canonicalIdentityValue($item), $value);
        }

        $canonical = [];
        foreach ($value as $key => $item) {
            $canonical[(string) $key] = self::canonicalIdentityValue($item);
        }
        ksort($canonical, SORT_STRING);

        return $canonical;
    }

    private static function normalizedText(\DOMElement $element): string
    {
        $text = preg_replace('/\s+/u', ' ', $element->textContent) ?? $element->textContent;

        return trim($text);
    }

    private static function camelCase(string $name): string
    {
        return preg_replace_callback(
            '/-([a-z])/',
            static fn (array $match): string => strtoupper($match[1]),
            $name
        ) ?? $name;
    }

    private static function odfTimeDurationFromDateTime(string $value): ?string
    {
        if (preg_match('/T(\d{2}):(\d{2})(?::(\d{2})(?:[.,]\d+)?)?(?:Z|[+-]\d{2}:?\d{2})?$/', trim($value), $match) !== 1) {
            return null;
        }

        return sprintf(
            'PT%02dH%02dM%02dS',
            (int) $match[1],
            (int) $match[2],
            isset($match[3]) && $match[3] !== '' ? (int) $match[3] : 0
        );
    }

    private static function kebabCase(string $name): string
    {
        $name = preg_replace('/(?<!^)[A-Z]/', '-$0', $name) ?? $name;

        return strtolower($name);
    }

    private function uniqueHeadingAnchor(string $text): string
    {
        $base = self::headingAnchorBase($text);

        return $this->uniqueHeadingAnchorFromBase($base);
    }

    private function uniqueHeadingAnchorFromBase(string $base): string
    {
        $base = $base === '' ? 'section' : $base;
        $seen = $this->headingAnchorUses[$base] ?? 0;
        $this->headingAnchorUses[$base] = $seen + 1;

        return $seen === 0 ? $base : $base . '-' . $seen;
    }

    private static function headingAnchorBase(string $text): string
    {
        $id = strtolower(trim($text));
        $id = preg_replace('/[^\pL\pN]+/u', '-', $id) ?? '';
        $id = trim($id, '-');

        return $id === '' ? 'section' : $id;
    }

    private static function slug(string $value): string
    {
        $slug = strtolower(preg_replace('/[^A-Za-z0-9]+/', '-', trim($value)) ?? '');
        $slug = trim($slug, '-');

        return $slug === '' ? 'odf-section' : $slug;
    }

    private static function bookmarkId(string $name): string
    {
        $id = strtolower(preg_replace('/[^A-Za-z0-9]+/', '-', trim($name)) ?? '');
        $id = trim($id, '-');

        return $id === '' ? 'odf-bookmark' : $id;
    }

    private static function referenceId(string $name): string
    {
        $id = strtolower(preg_replace('/[^A-Za-z0-9]+/', '-', trim($name)) ?? '');
        $id = trim($id, '-');

        return $id === '' ? 'odf-reference' : $id;
    }
}
